"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[83],{7083:e=>{e.exports=JSON.parse('{"schemaVersion":"1.0.0","title":{"en":"Questions to Review","zh":"待审核题目"},"notice":{"en":"These questions are not part of the approved study pool. They are shown only for later review and are not used in 10- or 30-question practice sessions.","zh":"这些题目不属于已审核学习题库。它们只供后续审核查看，不会进入 10 题或 30 题练习。"},"labels":{"reviewReason":{"en":"Why this question needs review","zh":"为什么这道题需要审核"},"sourceAnswer":{"en":"Source answer under review","zh":"原题答案（审核中）"}},"count":125,"questions":[{"id":"practice-nail-test-q004","question":{"en":"What substance causes the nails to heat up during acrylic nail application?","zh":"在涂敷丙烯酸甲过程中，哪种物质会使指甲发热？"},"choices":[{"id":"a","en":"Monomer","zh":"单体液"},{"id":"b","en":"Polymer","zh":"聚合物粉"},{"id":"c","en":"Primer","zh":"底剂"},{"id":"d","en":"Oligomer","zh":"低聚物"}],"sourceAnswer":{"en":"Primer","zh":"底剂"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q004"}],"reviewReason":{"en":"The source keys primer as the substance that causes heat during acrylic application. Heat is produced by the exothermic polymerization reaction, not by primer, so the keyed answer is not safe to teach.","zh":"原题把 primer（底涂）当成丙烯酸甲发热的原因。热量来自放热的聚合反应，不是来自底涂，所以这个原题答案不适合当作正确知识来教。"},"authorityRefs":[]},{"id":"practice-nail-test-q006","question":{"en":"What should you do to complete a gel service?","zh":"完成凝胶服务后应该做什么？"},"choices":[{"id":"a","en":"Apply nourishing oil to the client’s hands","zh":"在顾客手上涂抹营养油"},{"id":"b","en":"Soak a cotton ball with acetone and wrap it in aluminum foil","zh":"用丙酮浸湿棉球并用铝箔包裹"},{"id":"c","en":"wipe with cotton ball soaked in 99% isopropyl alcohol.","zh":"用浸有99%异丙醇的棉球擦拭。"},{"id":"d","en":"Reduce the time under the light","zh":"缩短照射时间"}],"sourceAnswer":{"en":"Apply nourishing oil to the client’s hands","zh":"在顾客手上涂抹营养油"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q006"}],"reviewReason":{"en":"The source says to finish a gel service by applying nourishing oil to the client\'s hands. Gel procedures typically apply cuticle oil to surrounding skin; the keyed body location and product are too vague.","zh":"原题说凝胶服务结束时要把营养油涂在客人手上。凝胶流程通常是把死皮油涂在指甲周围皮肤上；原题的部位和产品都太笼统，不能当作标准步骤。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Gel Services - Post-Service Procedure","printedPage":"374-382","pdfPage":398}]},{"id":"practice-nail-test-q007","question":{"en":"What to use if a client is allergic to one component in hand wash?","zh":"如果顾客对洗手液中的某一成分过敏，应使用什么？"},"choices":[{"id":"a","en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"},{"id":"b","en":"Put on gloves and ask the client to wash their hands","zh":"戴上手套并请顾客洗手"},{"id":"c","en":"Hospital-grade disinfection","zh":"医院级消毒"},{"id":"d","en":"Liquid disinfectant","zh":"液体消毒剂"}],"sourceAnswer":{"en":"Liquid disinfectant","zh":"液体消毒剂"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q007"}],"reviewReason":{"en":"The source recommends liquid disinfectant when a client is allergic to a hand-wash ingredient. Disinfectant is not a safe substitute for hand-washing product on skin.","zh":"原题建议：如果客人对洗手产品里的成分过敏，就改用液体消毒剂。消毒剂不能安全地代替皮肤上的洗手产品。"},"authorityRefs":[]},{"id":"practice-nail-test-q009","question":{"en":"How should salon workers reduce the risk of contaminating food with salon chemicals?","zh":"沙龙工作人员应如何降低食品被沙龙化学品污染的风险？"},"choices":[{"id":"a","en":"Keep food beside closed product containers","zh":"把食物放在已关闭的产品容器旁"},{"id":"b","en":"Eat only after covering the work table","zh":"盖住工作台后再进食"},{"id":"c","en":"Wash hands, then eat at the work desk","zh":"洗手后在工作台上进食"},{"id":"d","en":"Avoid eating at the work desk","zh":"避免在工作台上进食"}],"sourceAnswer":{"en":"Avoid eating at the work desk","zh":"避免在工作台上进食"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q009"}],"reviewReason":{"en":"The source answer is sensible general hygiene, but the textbook does not support the specific work-desk rule and the item cannot add a non-restating teaching fact from the available authority.","zh":"原题答案作为一般卫生建议说得通，但教材并不支持这条具体的工作台规则，现有资料也无法写出不重复题目本身的教学内容。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Chemistry and Chemical Safety - Chemical Safety","printedPage":"170-176","pdfPage":665}]},{"id":"practice-nail-test-q011","question":{"en":"What is the process of disinfecting bacteria called?","zh":"对细菌进行消毒的过程称为什么？"},"choices":[{"id":"a","en":"Immunity","zh":"免疫力"},{"id":"b","en":"Sterilization","zh":"灭菌"},{"id":"c","en":"Sanitation","zh":"清洁/卫生处理"},{"id":"d","en":"Cleaning","zh":"清洁"}],"sourceAnswer":{"en":"Sterilization","zh":"灭菌"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q011"}],"reviewReason":{"en":"On the infection-control ladder, disinfection is not sterilization. The source key treats these two different steps as the same.","zh":"在感染控制层级里，disinfection（消毒）不是 sterilization（灭菌）。原题答案把这两个不同步骤当成同一件事。"},"authorityRefs":[]},{"id":"practice-nail-test-q012","question":{"en":"How to remove gel nails?","zh":"如何卸除凝胶甲？"},"choices":[{"id":"a","en":"Apply nourishing oil to the client’s hands","zh":"在顾客手上涂抹营养油"},{"id":"b","en":"Apply oil to the skin","zh":"给皮肤涂油"},{"id":"c","en":"Soak a cotton ball with acetone and wrap it in aluminum foil","zh":"用丙酮浸湿棉球并用铝箔包裹"},{"id":"d","en":"Soak in acetone","zh":"浸泡在丙酮中"}],"sourceAnswer":{"en":"Soak in acetone","zh":"浸泡在丙酮中"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q012"}],"reviewReason":{"en":"The source says all gel nails are removed by soaking in acetone. Soak-off gels may be soaked, but hard gels must be filed off, so the generic key is unsafe.","zh":"原题说所有凝胶甲都可以用丙酮浸泡卸除。可浸泡凝胶可以泡除，但硬凝胶必须打磨去除，所以这个笼统答案不安全。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Removal","printedPage":"374-382","pdfPage":398}]},{"id":"practice-nail-test-q014","question":{"en":"What is the process of sterilizing using UV light in a salon called?","zh":"在沙龙中使用紫外线进行灭菌的过程称为什么？"},"choices":[{"id":"a","en":"Liquid disinfectant","zh":"液体消毒剂"},{"id":"b","en":"Hospital-grade disinfection","zh":"医院级消毒"},{"id":"c","en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"},{"id":"d","en":"Disinfect the entire table","zh":"消毒整个工作台"}],"sourceAnswer":{"en":"Hospital-grade disinfection","zh":"医院级消毒"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q014"}],"reviewReason":{"en":"The source describes UV-light cabinet use as hospital-grade disinfection/sterilization. A UV storage cabinet does not replace required cleaning and EPA-registered disinfection.","zh":"原题把紫外线柜子说成医院级消毒或灭菌。紫外线储存柜不能代替必须的清洁和 EPA 注册消毒剂消毒。"},"authorityRefs":[]},{"id":"practice-nail-test-q021","question":{"en":"What is the angle to file the corners of nails?","zh":"打磨指甲边角的角度是多少？"},"choices":[{"id":"a","en":"30 degrees","zh":"30度"},{"id":"b","en":"45 degrees","zh":"45度"},{"id":"c","en":"60 degrees","zh":"60度"},{"id":"d","en":"90 degrees","zh":"90度"}],"sourceAnswer":{"en":"60 degrees","zh":"60度"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q021"}],"reviewReason":{"en":"The source gives a universal 60-degree angle for filing nail corners. Filing direction and shape vary by desired nail shape; the textbook does not support this exact rule.","zh":"原题给出打磨指甲边角的统一 60 度规则。打磨方向和形状会随目标甲型变化，教材并不支持这条固定角度。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Manicuring - Nail Shapes and Filing","printedPage":"157-160","pdfPage":181}]},{"id":"practice-nail-test-q023","question":{"en":"What is used to file metal tips for paper files?","zh":"用于打磨纸质锉配套金属甲片的是什么？"},"choices":[{"id":"a","en":"Nail tip file","zh":"甲片锉"},{"id":"b","en":"Cuticle nippers","zh":"甲小皮钳"},{"id":"c","en":"Abrasive board","zh":"砂板锉"},{"id":"d","en":"Metal file","zh":"金属锉"}],"sourceAnswer":{"en":"Nail tip file","zh":"甲片锉"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q023"}],"reviewReason":{"en":"The phrase \'file metal tips for paper files\' does not identify a recognized implement or procedure. The keyed \'nail tip file\' does not resolve the damaged stem.","zh":"原题短语“file metal tips for paper files”无法对应公认的工具或步骤。原题答案“nail tip file”也补不了这道损坏的题目。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Manicuring - Files and Implements","printedPage":"139-148","pdfPage":163}]},{"id":"practice-nail-test-q024","question":{"en":"Which organ discharges waste containing bile?","zh":"哪个器官排出含有胆汁的废物？"},"choices":[{"id":"a","en":"Liver","zh":"肝脏"},{"id":"b","en":"Kidneys","zh":"肾脏"},{"id":"c","en":"Large intestine","zh":"大肠"},{"id":"d","en":"Skin","zh":"皮肤"}],"sourceAnswer":{"en":"Liver","zh":"肝脏"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q024"}],"reviewReason":{"en":"The source says the liver discharges waste containing bile. The liver produces bile, the gallbladder stores it, and the intestine eliminates waste; the stem combines different functions.","zh":"原题说肝脏排出含胆汁的废物。肝脏产生胆汁，胆囊储存胆汁，肠道排出废物；题目把不同功能混在一起了。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"General Anatomy - Digestive System and Liver","printedPage":"42-47","pdfPage":66}]},{"id":"practice-nail-test-q025","question":{"en":"Before nail tools are used on another client, what must happen?","zh":"美甲工具用于下一位顾客之前，必须做什么？"},"choices":[{"id":"a","en":"They must be returned to the workstation","zh":"必须放回工作台"},{"id":"b","en":"They must be placed in clean storage","zh":"必须放入清洁的储存处"},{"id":"c","en":"Used on another client","zh":"用于下一位顾客"},{"id":"d","en":"They must be sharpened","zh":"必须磨利"}],"sourceAnswer":{"en":"Used on another client","zh":"用于下一位顾客"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q025"}],"reviewReason":{"en":"The source question asks what must happen before tools are used on another client, but the keyed answer repeats \'used on another client\' and supplies no safety action.","zh":"原题问工具用到下一位客人之前必须做什么，但原题答案只是重复“用到另一位客人”，没有给出任何安全操作。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Cleaning and Disinfecting Implements","printedPage":"138-140","pdfPage":633}]},{"id":"practice-nail-test-q027","question":{"en":"What to recommend to a client who is allergic to liquid in acrylic nails?","zh":"对丙烯酸甲液体过敏的顾客应推荐什么？"},"choices":[{"id":"a","en":"Gel polish","zh":"凝胶甲油"},{"id":"b","en":"Builder gel","zh":"建构凝胶"},{"id":"c","en":"Oligomer","zh":"低聚物"},{"id":"d","en":"UV gel","zh":"UV凝胶"}],"sourceAnswer":{"en":"UV gel","zh":"UV凝胶"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q027"}],"reviewReason":{"en":"The source recommends UV gel for a client allergic to acrylic liquid. Many acrylic and gel systems share methacrylate allergens, so substitution without medical/product-specific guidance is unsafe.","zh":"原题建议对丙烯酸液体过敏的客人改用 UV 凝胶。许多丙烯酸和凝胶产品含有相关的 methacrylates 过敏原，没有医疗或产品说明就替换是不安全的。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Product Allergies","printedPage":"117-120","pdfPage":141}]},{"id":"practice-nail-test-q029","question":{"en":"If a client complains that their nails are hot and moist under the UV light, what might be the cause?","zh":"如果顾客抱怨在紫外线灯下指甲又热又湿，可能的原因是什么？"},"choices":[{"id":"a","en":"Incorrect usage of the UV light","zh":"紫外线灯使用不当"},{"id":"b","en":"The product overflowed onto the skin","zh":"产品溢到了皮肤上"},{"id":"c","en":"Incorrect polymer ratio,","zh":"聚合物比例不正确，"},{"id":"d","en":"The lamp was on too long","zh":"灯照时间过长"}],"sourceAnswer":{"en":"Incorrect usage of the UV light","zh":"紫外线灯使用不当"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q029"}],"reviewReason":{"en":"The keyed cause \'incorrect usage of the UV light\' is too vague and the symptom description does not identify a unique product, lamp, curing-time, or application error.","zh":"原题原因“UV 灯使用不正确”太含糊。症状描述也无法指向某一个产品、灯具、固化时间或操作错误。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Proper Curing","printedPage":"370-376","pdfPage":394}]},{"id":"practice-nail-test-q037","question":{"en":"What should be done first to start a pedicure service?","zh":"开始足部美甲护理服务时首先应做什么？"},"choices":[{"id":"a","en":"Liquid disinfectant","zh":"液体消毒剂"},{"id":"b","en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"},{"id":"c","en":"Put on gloves and ask the client to wash their hands","zh":"戴上手套并请顾客洗手"},{"id":"d","en":"Assess the condition of the injured finger","zh":"评估受伤手指的状况"}],"sourceAnswer":{"en":"Put on gloves and ask the client to wash their hands","zh":"戴上手套并请顾客洗手"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q037"}],"reviewReason":{"en":"The source says the first pedicure step is to put on gloves and ask the client to wash their hands. The textbook pre-service sequence requires technician hand washing and does not support this combined first step.","zh":"原题说足部护理的第一步是戴手套并请客人洗手。教材的服务前步骤要求技师先洗手，并不支持把这两件事合成第一步。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Pedicuring - Pre-Service Procedure","printedPage":"208-213","pdfPage":232}]},{"id":"practice-nail-test-q038","question":{"en":"To reduce the feeling of heat when the client is under the UV light, what should the technician do?","zh":"为减轻顾客在紫外线灯下的热感，技师应怎么做？"},"choices":[{"id":"a","en":"Reduce the time under the light","zh":"缩短照射时间"},{"id":"b","en":"Apply nourishing oil to the client’s hands","zh":"在顾客手上涂抹营养油"},{"id":"c","en":"wipe with cotton ball soaked in 99% isopropyl alcohol.","zh":"用浸有99%异丙醇的棉球擦拭。"},{"id":"d","en":"Soak a cotton ball with acetone and wrap it in aluminum foil","zh":"用丙酮浸湿棉球并用铝箔包裹"}],"sourceAnswer":{"en":"Reduce the time under the light","zh":"缩短照射时间"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q038"}],"reviewReason":{"en":"The source recommends reducing lamp time to reduce heat. Shortening required cure time can leave gel undercured and increase allergy and service-breakdown risk.","zh":"原题建议缩短灯照时间来减少发热。缩短必要的固化时间可能使凝胶固化不足，增加过敏和作品失败的风险。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Proper Curing","printedPage":"370-376","pdfPage":394}]},{"id":"practice-nail-test-q039","question":{"en":"How does applying tips differ from using acrylic gel?","zh":"贴甲片与使用丙烯酸凝胶有何不同？"},"choices":[{"id":"a","en":"With LED light only","zh":"仅使用LED灯"},{"id":"b","en":"UV light","zh":"紫外线灯"},{"id":"c","en":"Without any curing light","zh":"不使用任何固化灯"},{"id":"d","en":"By air drying","zh":"通过自然风干"}],"sourceAnswer":{"en":"UV light","zh":"紫外线灯"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q039"}],"reviewReason":{"en":"The stem asks how applying tips differs from acrylic gel, but the key \'UV light\' does not form a complete or unambiguous comparison. The intended fact cannot be recovered reliably.","zh":"题目问贴甲片和丙烯酸凝胶有何不同，但原题答案“UV light”不能形成完整、明确的对比。真正要考的事实无法可靠还原。"},"authorityRefs":[]},{"id":"practice-nail-test-q043","question":{"en":"After a service, if a client wants to know what type of nail polish to use at home, how should the technician advise them?","zh":"服务结束后，如果顾客想知道在家应使用哪种指甲油，技师应如何建议？"},"choices":[{"id":"a","en":"Use the fine side of the nail file","zh":"使用指甲锉的细面"},{"id":"b","en":"Use oil treatments for the nails","zh":"给指甲使用油类护理"},{"id":"c","en":"Schedule the client’s next appointment","zh":"为顾客预约下次服务"},{"id":"d","en":"Recommend a type that suits their nails","zh":"推荐适合其指甲的类型"}],"sourceAnswer":{"en":"Recommend a type that suits their nails","zh":"推荐适合其指甲的类型"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q043"}],"reviewReason":{"en":"The keyed advice to recommend polish that \'suits their nails\' is subjective and gives no condition, product property, or unique educational fact to review.","zh":"原题建议推荐“适合客人指甲”的指甲油，这很主观，没有给出甲况、产品特性或可审核的具体知识点。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Manicuring - Nail Coatings","printedPage":"149-153","pdfPage":173}]},{"id":"practice-nail-test-q044","question":{"en":"What file tip is used to file acrylic nails?","zh":"打磨丙烯酸甲应使用哪种锉头？"},"choices":[{"id":"a","en":"Carbide","zh":"硬质合金"},{"id":"b","en":"Ceramic","zh":"陶瓷"},{"id":"c","en":"Nickel","zh":"镍"},{"id":"d","en":"Diamond","zh":"金刚石"}],"sourceAnswer":{"en":"Nickel","zh":"镍"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q044"}],"reviewReason":{"en":"The source keys nickel as a file-tip material, but the textbook describes carbide, diamond, ceramic, and abrasive bands for electric-file bits; nickel appears only as an implement plating.","zh":"原题把 nickel（镍）当成磨头材料。教材里电动磨甲机磨头是碳化钨、金刚石、陶瓷和砂圈；镍只出现在工具镀层里。"},"authorityRefs":[]},{"id":"practice-nail-test-q046","question":{"en":"What is the chemical reaction that occurs when a monomer combines with a polymer?","zh":"单体液（monomer）与聚合物（polymer）结合时发生的化学反应是什么？"},"choices":[{"id":"a","en":"A physical change","zh":"物理变化"},{"id":"b","en":"Evaporation","zh":"蒸发"},{"id":"c","en":"A chemical reaction","zh":"化学反应"},{"id":"d","en":"Condensation","zh":"凝结"}],"sourceAnswer":{"en":"A chemical reaction","zh":"化学反应"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q046"}],"reviewReason":{"en":"The source answers a term question with the tautology \'a chemical reaction.\' The textbook term for the reaction that joins monomers into polymers is polymerization.","zh":"原题用“化学反应”来回答一个术语题，等于同义反复。教材里把单体连接成聚合物的反应名称是 polymerization（聚合）。"},"authorityRefs":[]},{"id":"practice-nail-test-q049","question":{"en":"What is another name for Hypertrophy?","zh":"肥厚（Hypertrophy）的另一名称是什么？"},"choices":[{"id":"a","en":"Leukonychia","zh":"白甲病"},{"id":"b","en":"Onychophagy","zh":"咬甲癖"},{"id":"c","en":"Onycholysis","zh":"甲剥离"},{"id":"d","en":"Onychauxis","zh":"甲肥厚（onychauxis）"}],"sourceAnswer":{"en":"Onychauxis","zh":"甲肥厚（onychauxis）"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q049"}],"reviewReason":{"en":"The source treats hypertrophy as another name for onychauxis. Hypertrophy is a general increase in tissue size, while onychauxis specifically describes abnormal nail thickening; they are not safe synonyms.","zh":"原题把 hypertrophy 当成 onychauxis 的别名。hypertrophy 泛指组织变大，onychauxis 特指指甲异常增厚；两者不能安全地当作同一词。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Disorders - Onychauxis","printedPage":"105-107","pdfPage":129}]},{"id":"practice-nail-test-q050","question":{"en":"What is the cause of a client\'s complaint about heat?","zh":"顾客抱怨发热的原因是什么？"},"choices":[{"id":"a","en":"The product overflowed onto the skin","zh":"产品溢到了皮肤上"},{"id":"b","en":"Incorrect usage of the UV light","zh":"紫外线灯使用不当"},{"id":"c","en":"Incorrect usage","zh":"使用不当"},{"id":"d","en":"The lamp was on too long","zh":"灯照时间过长"}],"sourceAnswer":{"en":"Incorrect usage","zh":"使用不当"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q050"}],"reviewReason":{"en":"The key \'Incorrect usage\' is too vague to identify or teach the cause of a client\'s heat complaint.","zh":"原题答案“Incorrect usage（使用不正确）”太含糊，无法说明或教学客人感觉发热的真正原因。"},"authorityRefs":[]},{"id":"practice-nail-test-q051","question":{"en":"When a client has a broken acrylic nail, where should the gel be thicker?","zh":"当顾客的丙烯酸甲断裂时，凝胶应在哪里更厚？"},"choices":[{"id":"a","en":"The arch of the nail","zh":"指甲的拱形处"},{"id":"b","en":"From the nail base to the tip","zh":"从甲根到甲尖"},{"id":"c","en":"At the point of attachment","zh":"贴在附着点"},{"id":"d","en":"Base of the nail","zh":"指甲基部"}],"sourceAnswer":{"en":"From the nail base to the tip","zh":"从甲根到甲尖"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q051"}],"reviewReason":{"en":"The source says gel on a broken acrylic nail should be thicker from base to tip. Proper structure requires controlled thickness in the stress area, not uniform thick product across the nail.","zh":"原题说断裂的丙烯酸甲上，凝胶要从甲根到甲尖都更厚。正确结构是在应力区控制厚度，而不是整甲均匀堆厚。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Enhancement Structure - Stress Area","printedPage":"262-263","pdfPage":286}]},{"id":"practice-nail-test-q052","question":{"en":"What is Sodium hypochlorite?","zh":"次氯酸钠是什么？"},"choices":[{"id":"a","en":"Floor cleaner or BLEACH","zh":"地板清洁剂或漂白剂（BLEACH）"},{"id":"b","en":"Isopropyl alcohol","zh":"异丙醇"},{"id":"c","en":"Hydrogen peroxide","zh":"过氧化氢"},{"id":"d","en":"Acetone","zh":"丙酮"}],"sourceAnswer":{"en":"Floor cleaner or BLEACH","zh":"地板清洁剂或漂白剂（BLEACH）"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q052"}],"reviewReason":{"en":"The source equates sodium hypochlorite with either floor cleaner or bleach. It is the active chemical in chlorine bleach, but not every floor cleaner is sodium hypochlorite.","zh":"原题把 sodium hypochlorite（次氯酸钠）等同于地板清洁剂或漂白水。它是含氯漂白水里的有效成分，但不是每一种地板清洁剂都是次氯酸钠。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Sodium Hypochlorite","printedPage":"119-123","pdfPage":614}]},{"id":"practice-nail-test-q056","question":{"en":"What should be recommended to a client who doesn\'t want fake nails but still wants a nail service?","zh":"对不想做假甲但仍想做美甲服务的顾客应推荐什么？"},"choices":[{"id":"a","en":"UV gel","zh":"UV凝胶"},{"id":"b","en":"Oligomer","zh":"低聚物"},{"id":"c","en":"Gel polish","zh":"凝胶甲油"},{"id":"d","en":"Builder gel","zh":"建构凝胶"}],"sourceAnswer":{"en":"Builder gel","zh":"建构凝胶"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q056"}],"reviewReason":{"en":"The client asks for no artificial nails, but the source recommends builder gel, which is an enhancement product. The answer conflicts with the client\'s stated choice.","zh":"客人明确不想做假甲，原题却推荐 builder gel（建构凝胶），这属于增强产品。答案与客人的选择冲突。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Product Types","printedPage":"370-376","pdfPage":394}]},{"id":"practice-nail-test-q058","question":{"en":"What should be done with chemical containers after they are empty?","zh":"化学药品容器清空后应如何处理？"},"choices":[{"id":"a","en":"Put on gloves and ask the client to wash their hands","zh":"戴上手套并请顾客洗手"},{"id":"b","en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"},{"id":"c","en":"Liquid disinfectant","zh":"液体消毒剂"},{"id":"d","en":"Rinse, Dry and Dispose of them","zh":"冲洗、晾干后丢弃"}],"sourceAnswer":{"en":"Rinse, Dry and Dispose of them","zh":"冲洗、晾干后丢弃"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q058"}],"reviewReason":{"en":"The source gives one universal rinse-dry-dispose rule for empty chemical containers. Disposal must follow the product label and local requirements; some containers should not be rinsed.","zh":"原题给空化学容器规定了统一的冲洗、晾干、丢弃方法。处置必须遵循产品标签和当地规定；有些容器不应冲洗。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Chemistry and Chemical Safety - Disposal","printedPage":"173","pdfPage":668}]},{"id":"practice-nail-test-q059","question":{"en":"How should fake nails be attached during acrylic nail application?","zh":"涂敷丙烯酸甲时假甲应如何贴附？"},"choices":[{"id":"a","en":"Soak in acetone","zh":"浸泡在丙酮中"},{"id":"b","en":"Wear a mask to protect from dust","zh":"戴口罩防尘"},{"id":"c","en":"Securely under the tip of the natural nail","zh":"牢固地贴在真甲游离缘下方"},{"id":"d","en":"The skin must be dry","zh":"皮肤必须干燥"}],"sourceAnswer":{"en":"Securely under the tip of the natural nail","zh":"牢固地贴在真甲游离缘下方"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q059"}],"reviewReason":{"en":"The instruction to attach fake nails \'securely under the tip of the natural nail\' does not describe a recognized tip, form, or full-cover application and could place product incorrectly.","zh":"原题说把假甲“牢固贴在真甲甲尖下方”，这不是公认的甲片、甲模或全贴应用方法，还可能把产品放错位置。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Tips - Application and Contact Area","printedPage":"252-260","pdfPage":276}]},{"id":"practice-nail-test-q060","question":{"en":"How should a metal cuticle tool be used?","zh":"金属甲小皮工具应如何使用？"},"choices":[{"id":"a","en":"Under the free edge with the point","zh":"用尖端伸到游离缘下方"},{"id":"b","en":"At a steep angle with firm pressure","zh":"以陡角度用力施压"},{"id":"c","en":"Horizontally, gently pressing on the nail bed","zh":"水平方向，轻轻按压甲床"},{"id":"d","en":"On dry tissue with a sawing motion","zh":"在干燥组织上来回锯动"}],"sourceAnswer":{"en":"Horizontally, gently pressing on the nail bed","zh":"水平方向，轻轻按压甲床"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q060"}],"reviewReason":{"en":"The source says to press a metal cuticle tool on the nail bed. The textbook procedure uses gentle pressure on the moist nail plate and avoids injury to living tissue.","zh":"原题说把金属死皮工具压在 nail bed（甲床）上。教材做法是在湿润的 nail plate（甲板）上轻轻施压，避免伤到活组织。"},"authorityRefs":[]},{"id":"practice-nail-test-q061","question":{"en":"What type of gel binds the polymer and monomer?","zh":"哪种凝胶结合聚合物（polymer）和单体液（monomer）？"},"choices":[{"id":"a","en":"UV gel","zh":"UV凝胶"},{"id":"b","en":"Oligomer","zh":"低聚物"},{"id":"c","en":"Gel polish","zh":"凝胶甲油"},{"id":"d","en":"Builder gel","zh":"建构凝胶"}],"sourceAnswer":{"en":"Builder gel","zh":"建构凝胶"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q061"}],"reviewReason":{"en":"The source says builder gel binds polymer and monomer. Builder gel is not the agent that combines liquid monomer and polymer powder; the premise is chemically unsound.","zh":"原题说 builder gel 能结合 polymer 和 monomer。建构凝胶并不是把液体单体和聚合物粉结合在一起的物质，这个前提在化学上不成立。"},"authorityRefs":[]},{"id":"practice-nail-test-q063","question":{"en":"How to check nail strength?","zh":"如何检查指甲强度？"},"choices":[{"id":"a","en":"Wear a mask to protect from dust","zh":"戴口罩防尘"},{"id":"b","en":"Securely under the tip of the natural nail","zh":"牢固地贴在真甲游离缘下方"},{"id":"c","en":"By applying pressure at the tip","zh":"在甲尖施加压力"},{"id":"d","en":"The skin must be dry","zh":"皮肤必须干燥"}],"sourceAnswer":{"en":"By applying pressure at the tip","zh":"在甲尖施加压力"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q063"}],"reviewReason":{"en":"The source recommends checking nail strength by pressing at the tip without defining natural or enhanced nails, safe pressure, or the stress area. The procedure is too vague.","zh":"原题建议按压甲尖来检查指甲强度，但没有说明是天然甲还是增强甲、安全力度，或应力区在哪里。这个步骤太含糊。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Enhancement Structure - Stress Area","printedPage":"262-263","pdfPage":286}]},{"id":"practice-nail-test-q065","question":{"en":"What should be used to treat split nails?","zh":"处理开裂指甲应使用什么？"},"choices":[{"id":"a","en":"Cuticle oil","zh":"甲小皮油"},{"id":"b","en":"Nail polish remover","zh":"卸甲液"},{"id":"c","en":"Nail adhesive","zh":"美甲粘合剂"},{"id":"d","en":"Primer","zh":"底剂"}],"sourceAnswer":{"en":"Cuticle oil","zh":"甲小皮油"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q065"}],"reviewReason":{"en":"Cuticle oil can improve flexibility and dryness but does not treat or repair a split nail. The word \'treat\' overstates what the product can do.","zh":"死皮油可以改善柔软度和干燥，但不能治疗或修复裂甲。“treat（治疗）”这个词夸大了产品作用。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Disorders - Split and Brittle Nails","printedPage":"107","pdfPage":131}]},{"id":"practice-nail-test-q068","question":{"en":"What percentage of bacteria are harmless?","zh":"多少比例的细菌是无害的？"},"choices":[{"id":"a","en":"around 99% of bacteria are harmless","zh":"约99%的细菌是无害的"},{"id":"b","en":"around 75% of bacteria are harmless","zh":"大约75%的细菌无害"},{"id":"c","en":"around 50% of bacteria are harmless","zh":"大约50%的细菌无害"},{"id":"d","en":"around 25% of bacteria are harmless","zh":"大约25%的细菌无害"}],"sourceAnswer":{"en":"around 99% of bacteria are harmless","zh":"约99%的细菌是无害的"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q068"}],"reviewReason":{"en":"The source assigns an unsupported exact figure of about 99 percent harmless bacteria. The textbook says most bacteria are nonpathogenic but does not support this percentage.","zh":"原题给出约 99% 细菌无害这个没有依据的精确数字。教材说大多数细菌是非致病的，但并不支持这个百分比。"},"authorityRefs":[]},{"id":"practice-nail-test-q070","question":{"en":"What is the chemical smell in the working room called?","zh":"工作室内的化学气味称为什么？"},"choices":[{"id":"a","en":"Fumes","zh":"烟雾/挥发气体"},{"id":"b","en":"Smoke","zh":"烟雾"},{"id":"c","en":"Dust","zh":"粉尘"},{"id":"d","en":"Mist","zh":"雾滴"}],"sourceAnswer":{"en":"Fumes","zh":"烟雾/挥发气体"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q070"}],"reviewReason":{"en":"The source equates a chemical smell with fumes. Odor alone does not identify fumes or exposure level, and the textbook defines fumes more specifically than a smell in the room.","zh":"原题把化学气味等同于 fumes（烟雾/挥发物）。单靠气味不能判断是不是烟雾，也不能判断暴露程度；教材对 fumes 的定义比“房间里有味道”更具体。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Vapors, Dusts, and Fumes","printedPage":"126-130","pdfPage":150}]},{"id":"practice-nail-test-q073","question":{"en":"What is used to shape the free edge of acrylic nails?","zh":"用于塑形丙烯酸甲游离缘的是什么？"},"choices":[{"id":"a","en":"Metal file","zh":"金属锉"},{"id":"b","en":"Abrasive board","zh":"砂板锉"},{"id":"c","en":"Carbide bit","zh":"硬质合金磨头"},{"id":"d","en":"Chamois buffer","zh":"麂皮抛光器"}],"sourceAnswer":{"en":"Metal file","zh":"金属锉"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q073"}],"reviewReason":{"en":"Several abrasives can shape an acrylic free edge; the generic stem does not make \'metal file\' uniquely correct.","zh":"多种打磨工具都可以修丙烯酸甲的游离缘；题目太笼统，不能证明只有“金属锉”才正确。"},"authorityRefs":[]},{"id":"practice-nail-test-q077","question":{"en":"What is the most important safety measure when performing acrylic nail services?","zh":"进行丙烯酸甲服务时最重要的安全措施是什么？"},"choices":[{"id":"a","en":"Work without ventilation","zh":"在没有通风的环境中操作"},{"id":"b","en":"Work with bare hands","zh":"徒手操作"},{"id":"c","en":"Eat at the work desk","zh":"在工作台上进食"},{"id":"d","en":"Protective gear","zh":"防护装备"}],"sourceAnswer":{"en":"Protective gear","zh":"防护装备"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q077"}],"reviewReason":{"en":"\'Protective gear\' is too broad for a most-important safety question, and several specific protective measures could also be correct.","zh":"“防护装备”对“最重要的安全措施”这类题来说太宽。多种具体防护做法也可能正确。"},"authorityRefs":[]},{"id":"practice-nail-test-q080","question":{"en":"What is strong massage on the surface of the arm called?","zh":"在手臂表面进行的强力按摩称为什么？"},"choices":[{"id":"a","en":"Petrissage","zh":"揉捏法"},{"id":"b","en":"Joint relaxer Movement","zh":"关节放松动作"},{"id":"c","en":"Deep tissue massage","zh":"深层组织按摩"},{"id":"d","en":"Tapotement","zh":"叩击法"}],"sourceAnswer":{"en":"Deep tissue massage","zh":"深层组织按摩"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q080"}],"reviewReason":{"en":"\'Strong massage on the surface of the arm\' does not uniquely define deep-tissue massage and does not match the textbook\'s named basic massage movements.","zh":"“在手臂表面做强力按摩”并不能唯一定义深层组织按摩，也不符合教材里命名的基本按摩手法。"},"authorityRefs":[]},{"id":"practice-nail-test-q081","question":{"en":"How should the toenail shape be styled?","zh":"脚趾甲应如何修形？"},"choices":[{"id":"a","en":"Straight across","zh":"平直剪"},{"id":"b","en":"Straight","zh":"修直"},{"id":"c","en":"Straight with slightly rounded corners","zh":"平直、边角略圆"},{"id":"d","en":"Oval-shaped","zh":"椭圆形"}],"sourceAnswer":{"en":"Straight with slightly rounded corners","zh":"平直、边角略圆"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q081"}],"reviewReason":{"en":"The source recommends slightly rounded toenail corners. General safety guidance is to trim toenails straight across to reduce ingrown-nail risk, so this wording should not ship as a rule.","zh":"原题建议脚趾甲边角略圆。一般安全做法是把脚趾甲剪成平直，以减少嵌甲风险，所以这句不应作为规则发布。"},"authorityRefs":[]},{"id":"practice-nail-test-q083","question":{"en":"What is the name of the finger massage technique?","zh":"手指按摩手法的名称是什么？"},"choices":[{"id":"a","en":"Petrissage","zh":"揉捏法"},{"id":"b","en":"Shiatsu or Effeurage","zh":"指压（Shiatsu）或轻抚法（Effleurage）"},{"id":"c","en":"Deep tissue massage","zh":"深层组织按摩"},{"id":"d","en":"Joint relaxer Movement","zh":"关节放松动作"}],"sourceAnswer":{"en":"Shiatsu or Effeurage","zh":"指压（Shiatsu）或轻抚法（Effleurage）"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q083"}],"reviewReason":{"en":"The keyed answer gives two different massage techniques (\'Shiatsu or Effleurage\'), so the item has no single defensible correct choice.","zh":"原题答案给出两种不同按摩手法（Shiatsu 或 Effleurage），因此没有一个可以单独成立的正确答案。"},"authorityRefs":[]},{"id":"practice-nail-test-q088","question":{"en":"Which monomer has the lightest fragrance?","zh":"哪种单体气味最轻？"},"choices":[{"id":"a","en":"Ethyl acrylic","zh":"乙基丙烯酸酯"},{"id":"b","en":"Methyl methacrylate","zh":"甲基丙烯酸甲酯（MMA）"},{"id":"c","en":"Methacrylic Acid","zh":"甲基丙烯酸"},{"id":"d","en":"Odorless monomer liquid","zh":"无味单体液"}],"sourceAnswer":{"en":"Ethyl acrylic","zh":"乙基丙烯酸酯"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q088"}],"reviewReason":{"en":"The keyed term \'Ethyl acrylic\' is not a recognized monomer name. The likely intended term is ethyl methacrylate, but the source wording is not reliable enough to silently correct.","zh":"原题术语 Ethyl acrylic 不是公认的单体名称。可能想说 ethyl methacrylate，但原文不够可靠，不能悄悄改掉。"},"authorityRefs":[]},{"id":"practice-nail-test-q090","question":{"en":"A client who has acrylic nails complains that the nails cracked in the middle. What might be the cause?","zh":"顾客的水晶甲在中间开裂，可能是什么原因？"},"choices":[{"id":"a","en":"Incorrect usage of the UV light","zh":"紫外线灯使用不当"},{"id":"b","en":"Incorrect polymer ratio,","zh":"聚合物比例不正确，"},{"id":"c","en":"The lamp was on too long","zh":"灯照时间过长"},{"id":"d","en":"The product overflowed onto the skin","zh":"产品溢到了皮肤上"}],"sourceAnswer":{"en":"Incorrect polymer ratio,","zh":"聚合物比例不正确，"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q090"}],"reviewReason":{"en":"The key \'incorrect polymer ratio\' does not state whether the bead was too wet or too dry and cannot uniquely explain a crack in the middle of an enhancement.","zh":"原题“polymer 比例不正确”没有说明粉珠太湿还是太干，也不能单独解释增强甲中间开裂的原因。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Monomer Liquid and Polymer Powder - Mix Ratio","printedPage":"324-330","pdfPage":348}]},{"id":"practice-nail-test-q091","question":{"en":"The largest bone in the knee area is?","zh":"膝盖部位最大的骨头是什么？"},"choices":[{"id":"a","en":"Calcaneus","zh":"跟骨"},{"id":"b","en":"Talus","zh":"距骨（Talus）"},{"id":"c","en":"Metatarsals","zh":"跖骨"},{"id":"d","en":"Patella","zh":"髌骨"}],"sourceAnswer":{"en":"Patella","zh":"髌骨"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q091"}],"reviewReason":{"en":"The source calls the patella the largest bone in the knee area. The patella is the largest sesamoid bone; the femur is the body\'s largest bone. The stem is too imprecise to ship with this key.","zh":"原题把 patella（髌骨）说成膝盖附近最大的骨头。髌骨是最大的籽骨；人体最大的骨头是 femur（股骨）。题目措辞太不精确，不能带着这个答案发布。"},"authorityRefs":[]},{"id":"practice-nail-test-q092","question":{"en":"What nail tip shape should be used for a round nail?","zh":"圆形指甲应使用什么甲片形状？"},"choices":[{"id":"a","en":"Straight with slightly rounded corners","zh":"平直、边角略圆"},{"id":"b","en":"Oval-shaped","zh":"椭圆形"},{"id":"c","en":"Straight","zh":"修直"},{"id":"d","en":"Straight across","zh":"平直剪"}],"sourceAnswer":{"en":"Oval-shaped","zh":"椭圆形"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q092"}],"reviewReason":{"en":"The source says a round natural nail requires an oval tip. Tip shape should fit the nail and desired result; the generic stem does not make oval uniquely correct.","zh":"原题说圆形真甲必须用椭圆形甲片。甲片形状应匹配指甲和目标效果；笼统题目不能证明只有椭圆形才正确。"},"authorityRefs":[]},{"id":"practice-nail-test-q093","question":{"en":"When applying a nail tip, where should it be attached?","zh":"贴甲片时，应贴在哪里？"},"choices":[{"id":"a","en":"From the nail base to the tip","zh":"从甲根到甲尖"},{"id":"b","en":"Base of the nail","zh":"指甲基部"},{"id":"c","en":"At the tip\'s edge and the stopping point at the nail tip","zh":"贴在甲片边缘和甲片止点处"},{"id":"d","en":"At the point of attachment","zh":"贴在附着点"}],"sourceAnswer":{"en":"At the tip\'s edge and the stopping point at the nail tip","zh":"贴在甲片边缘和甲片止点处"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q093"}],"reviewReason":{"en":"The keyed placement \'at the tip\'s edge and the stopping point at the nail tip\' is unclear and does not identify the contact area, stop point, or sidewall fit safely.","zh":"原题位置“在甲片边缘，停止点在甲尖”意思不清，不能安全说明接触区、停止点或侧壁贴合。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Tips - Application and Stop Point","printedPage":"252-260","pdfPage":276}]},{"id":"practice-nail-test-q096","question":{"en":"Which type of light can be used for treatment?","zh":"哪种光可用于治疗？"},"choices":[{"id":"a","en":"Heat therapy","zh":"热疗"},{"id":"b","en":"Water therapy","zh":"水疗"},{"id":"c","en":"Light therapy","zh":"光疗"},{"id":"d","en":"Massage therapy","zh":"按摩疗法"}],"sourceAnswer":{"en":"Light therapy","zh":"光疗"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q096"}],"reviewReason":{"en":"The stem asks which type of light can be used for treatment but keys \'light therapy,\' which is the treatment category rather than a type of light.","zh":"题目问哪种光可以用于治疗，原题答案却是 light therapy（光疗）。那是治疗类别，不是一种光。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Electricity and Light Therapy - Light Therapy","printedPage":"191-194","pdfPage":686}]},{"id":"practice-nail-test-q099","question":{"en":"If a client wants to remove gel nails but does not have the proper tool, what should they do?","zh":"如果顾客想卸除凝胶甲但没有合适工具，应怎么做？"},"choices":[{"id":"a","en":"Apply nourishing oil to the client’s hands","zh":"在顾客手上涂抹营养油"},{"id":"b","en":"wipe with cotton ball soaked in 99% isopropyl alcohol.","zh":"用浸有99%异丙醇的棉球擦拭。"},{"id":"c","en":"Soak a cotton ball with acetone and wrap it in aluminum foil","zh":"用丙酮浸湿棉球并用铝箔包裹"},{"id":"d","en":"Reduce the time under the light","zh":"缩短照射时间"}],"sourceAnswer":{"en":"Soak a cotton ball with acetone and wrap it in aluminum foil","zh":"用丙酮浸湿棉球并用铝箔包裹"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q099"}],"reviewReason":{"en":"The source treats all gel nails as acetone soak-off products. Hard gels must be filed off, so foil-and-acetone removal is not a safe generic instruction.","zh":"原题把所有凝胶甲都当成可用丙酮浸泡卸除的产品。硬凝胶必须打磨去除，所以锡纸加丙酮不是安全的通用卸甲方法。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Removal","printedPage":"378-382","pdfPage":402}]},{"id":"practice-nail-test-q104","question":{"en":"Which nail shape is the weakest?","zh":"哪种甲型最脆弱？"},"choices":[{"id":"a","en":"Square","zh":"方形"},{"id":"b","en":"Stiletto Nail Shape","zh":"尖锥形甲型"},{"id":"c","en":"Squoval","zh":"方圆形"},{"id":"d","en":"Almond","zh":"杏仁形"}],"sourceAnswer":{"en":"Stiletto Nail Shape","zh":"尖锥形甲型"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q104"}],"reviewReason":{"en":"Calling stiletto the universally weakest shape ignores length, product, apex, and structure. The textbook does not support one shape as uniquely weakest in every case.","zh":"把 stiletto（尖形甲）说成永远最弱的甲型，忽略了长度、产品、apex（应力高点）和结构。教材并不支持某一种甲型在所有情况下都最弱。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Manicuring - Nail Shapes","printedPage":"158-159","pdfPage":182}]},{"id":"practice-nail-test-q113","question":{"en":"If a client complains about heat during a gel manicure, what is the likely cause?","zh":"如果顾客在凝胶手部美甲护理过程中抱怨发热，可能原因是什么？"},"choices":[{"id":"a","en":"The product overflowed onto the skin","zh":"产品溢到了皮肤上"},{"id":"b","en":"The lamp was on too long","zh":"灯照时间过长"},{"id":"c","en":"Incorrect usage of the UV light","zh":"紫外线灯使用不当"},{"id":"d","en":"Too much adhesive used","zh":"使用了过多黏合剂"}],"sourceAnswer":{"en":"The lamp was on too long","zh":"灯照时间过长"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q113"}],"reviewReason":{"en":"A heat spike can result from thick product, damaged nails, lamp mismatch, or curing chemistry. \'Lamp on too long\' is not a unique or sufficiently safe diagnosis.","zh":"突然发热可能来自产品过厚、指甲受损、灯不匹配或固化化学反应。“灯开太久”不是唯一、也不足够安全的判断。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Proper Curing","printedPage":"370-376","pdfPage":394}]},{"id":"practice-nail-test-q115","question":{"en":"When massaging the client\'s hand, the technique used is called?","zh":"按摩顾客手部时使用的手法叫什么？"},"choices":[{"id":"a","en":"Deep tissue massage","zh":"深层组织按摩"},{"id":"b","en":"Tapotement","zh":"叩击法"},{"id":"c","en":"Petrissage","zh":"揉捏法"},{"id":"d","en":"Joint relaxer Movement","zh":"关节放松动作"}],"sourceAnswer":{"en":"Tapotement","zh":"叩击法"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q115"}],"reviewReason":{"en":"Several massage techniques can be used on the hand; the generic stem does not uniquely identify tapotement.","zh":"手上可以使用多种按摩手法；题目太笼统，不能唯一定为 tapotement（叩击法）。"},"authorityRefs":[]},{"id":"practice-nail-test-q117","question":{"en":"When should a client remove acrylic nails?","zh":"顾客应什么时候卸除水晶甲？"},"choices":[{"id":"a","en":"6 months","zh":"6个月"},{"id":"b","en":"20 seconds","zh":"20秒"},{"id":"c","en":"at Consultation","zh":"咨询时"},{"id":"d","en":"Every 2-3 weeks and maximum of 4 weeks","zh":"每2到3周，最长4周"}],"sourceAnswer":{"en":"Every 2-3 weeks and maximum of 4 weeks","zh":"每2到3周，最长4周"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q117"}],"reviewReason":{"en":"Two to three weeks is a common maintenance/fill interval, not a universal requirement to remove acrylic nails. The source wording would teach an incorrect rule.","zh":"两到三周常见于补甲或维护，并不是必须卸除丙烯酸甲的普遍规定。原题措辞会教错规则。"},"authorityRefs":[]},{"id":"practice-nail-test-q119","question":{"en":"What should be used to clean the tip of the nails?","zh":"清洁指甲尖应使用什么？"},"choices":[{"id":"a","en":"Cuticle nippers","zh":"甲小皮钳"},{"id":"b","en":"A cotton-tipped stick","zh":"棉头棒"},{"id":"c","en":"A cotton-tipped wooden stick","zh":"棉头木棒"},{"id":"d","en":"A clean spatula","zh":"干净的刮勺"}],"sourceAnswer":{"en":"A cotton-tipped wooden stick","zh":"棉头木棒"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q119"}],"reviewReason":{"en":"The source recommends a cotton-tipped wooden stick to clean under nail tips. Current procedure favors washing with a nail brush or an appropriate blunt implement; fibers can remain behind.","zh":"原题建议用棉头木签清洁甲片下方。现行做法更主张用指甲刷或合适的钝头工具清洗；棉纤维可能残留。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Hand and Nail Washing","printedPage":"135","pdfPage":630}]},{"id":"practice-nail-test-q120","question":{"en":"The French tip nail shape is suitable for people with?","zh":"法式甲片形状适合什么人？"},"choices":[{"id":"a","en":"Square","zh":"方形"},{"id":"b","en":"Short round nails","zh":"短圆形指甲"},{"id":"c","en":"Squoval","zh":"方圆形"},{"id":"d","en":"Oval","zh":"椭圆形"}],"sourceAnswer":{"en":"Short round nails","zh":"短圆形指甲"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q120"}],"reviewReason":{"en":"Short round nails do not uniquely require a French tip design. This is a style preference, not a technical suitability rule.","zh":"短圆形指甲并不必须做法式甲尖。这是风格偏好，不是技术上的唯一适合规则。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Manicuring - Nail Shapes and French Manicure","printedPage":"157-160","pdfPage":181}]},{"id":"practice-nail-test-q121","question":{"en":"A chemical solution used to prevent the growth of germs is called?","zh":"用于防止细菌生长的化学溶液叫什么？"},"choices":[{"id":"a","en":"Cleaning agents for all surfaces","zh":"适用于所有表面的清洁剂"},{"id":"b","en":"Disinfectants only","zh":"仅表面消毒剂"},{"id":"c","en":"Antiseptics only","zh":"仅皮肤抗菌剂"},{"id":"d","en":"Disinfectants for surfaces and Antiseptics for living tissue","zh":"用于表面的消毒剂，以及用于活组织的防腐剂"}],"sourceAnswer":{"en":"Disinfectants for surfaces and Antiseptics for living tissue","zh":"用于表面的消毒剂，以及用于活组织的防腐剂"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q121"}],"reviewReason":{"en":"The stem asks for one chemical solution but the key combines disinfectants for surfaces with antiseptics for skin. These are different product categories, so there is no single keyed answer.","zh":"题目只要一种化学溶液，原题答案却把物体表面消毒剂和皮肤防腐剂混在一起。这是不同产品类别，所以没有单一正确答案。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Disinfectants and Antiseptics","printedPage":"118-126","pdfPage":613}]},{"id":"practice-nail-test-q122","question":{"en":"If a client comes to the salon with a bandaged finger but still wants a service, what should the technician do?","zh":"如果顾客带着包扎的手指出现在沙龙但仍想接受服务，技师应怎么做？"},"choices":[{"id":"a","en":"Liquid disinfectant","zh":"液体消毒剂"},{"id":"b","en":"Assess the condition of the injured finger","zh":"评估受伤手指的状况"},{"id":"c","en":"Put on gloves and ask the client to wash their hands","zh":"戴上手套并请顾客洗手"},{"id":"d","en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"}],"sourceAnswer":{"en":"Assess the condition of the injured finger","zh":"评估受伤手指的状况"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q122"}],"reviewReason":{"en":"The source says to assess a bandaged finger but does not define whether the wound is open, infected, or safe to expose. Removing or inspecting a client\'s bandage is outside a clear salon safety procedure.","zh":"原题说要检查包扎的手指，但没有说明伤口是否开放、感染，或能否露出。拆开或检查客人绷带超出了明确的沙龙安全程序。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Open Wounds and Exposure Incidents","printedPage":"126-143","pdfPage":621}]},{"id":"practice-nail-test-q124","question":{"en":"Can you serve a client with moldy and fungal nails?","zh":"可以为有霉菌和真菌指甲的顾客服务吗？"},"choices":[{"id":"a","en":"Put on gloves and ask the client to wash their hands","zh":"戴上手套并请顾客洗手"},{"id":"b","en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"},{"id":"c","en":"Liquid disinfectant","zh":"液体消毒剂"},{"id":"d","en":"Remove the artificial nails first","zh":"先去除人工指甲"}],"sourceAnswer":{"en":"Remove the artificial nails first","zh":"先去除人工指甲"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q124"}],"reviewReason":{"en":"The source says to remove artificial nails from a client with suspected mold or fungal disease. A nail technician should not diagnose or work on a suspected infection; the item needs a safety rewrite.","zh":"原题说怀疑有霉菌或真菌时先卸假甲。美甲师不应诊断或在疑似感染上操作；这道题需要按安全要求重写。"},"authorityRefs":[]},{"id":"practice-nail-test-q125","question":{"en":"When bacteria invade living organisms (70%) without causing illness, they are referred to as?","zh":"当细菌侵入生物体（70%）但不引起疾病时，它们被称为什么？"},"choices":[{"id":"a","en":"Rod Shaped","zh":"棒形"},{"id":"b","en":"Symbiotic organisms","zh":"共生生物"},{"id":"c","en":"Infectious organisms","zh":"感染性有机体"},{"id":"d","en":"Wet Sanitizer","zh":"湿式卫生处理剂"}],"sourceAnswer":{"en":"Symbiotic organisms","zh":"共生生物"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q125"}],"reviewReason":{"en":"The source says bacteria invade living organisms 70 percent of the time without illness and calls them symbiotic. The percentage and use of \'invade\' are unsupported and biologically misleading.","zh":"原题说细菌有 70% 的时间侵入生物体却不致病，并称之为共生。这个百分比和“invade（侵入）”都没有依据，在生物学上会误导。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Pathogenic and Nonpathogenic Bacteria","printedPage":"103-106","pdfPage":598}]},{"id":"practice-nail-test-q126","question":{"en":"What should be used to clean the nail tips?","zh":"清洁甲片应使用什么？"},"choices":[{"id":"a","en":"A cotton-tipped wooden stick","zh":"棉头木棒"},{"id":"b","en":"A clean spatula","zh":"干净的刮勺"},{"id":"c","en":"A cotton-tipped stick","zh":"棉头棒"},{"id":"d","en":"Cuticle nippers","zh":"甲小皮钳"}],"sourceAnswer":{"en":"A cotton-tipped stick","zh":"棉头棒"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q126"}],"reviewReason":{"en":"The source recommends a cotton-tipped stick for cleaning nail tips without identifying the service or material. The procedure is not uniquely safe or supported.","zh":"原题建议用棉签清洁甲尖，但没有说明是什么服务或材料。这个步骤既不是唯一安全做法，也没有足够依据。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Hand and Nail Washing","printedPage":"135","pdfPage":630}]},{"id":"practice-nail-test-q127","question":{"en":"Why does the nail become rough after using an electric file?","zh":"为什么使用电动磨甲机后指甲会变粗糙？"},"choices":[{"id":"a","en":"The lamp was on too long","zh":"灯照时间过长"},{"id":"b","en":"The product overflowed onto the skin","zh":"产品溢到了皮肤上"},{"id":"c","en":"Incorrect usage of the UV light","zh":"紫外线灯使用不当"},{"id":"d","en":"Incorrect filing technique","zh":"修磨技术不正确"}],"sourceAnswer":{"en":"Incorrect filing technique","zh":"修磨技术不正确"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q127"}],"reviewReason":{"en":"The source explains roughness only as \'incorrect filing technique\' without identifying pressure, bit, angle, grit, or movement. The key is too vague to teach.","zh":"原题把粗糙只解释成“打磨手法不正确”，没有说明力度、磨头、角度、砂目或动作。这个答案太含糊，没法教学。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Electric Filing - Safe Technique","printedPage":"240-248","pdfPage":264}]},{"id":"practice-nail-test-q128","question":{"en":"Which type of gel prevents color fading and keeps the nail tips intact without using a UV lamp?","zh":"哪种凝胶可以防止颜色褪色，并且不使用紫外线灯也能保持甲片完整？"},"choices":[{"id":"a","en":"Oligomer","zh":"低聚物"},{"id":"b","en":"Builder gel","zh":"建构凝胶"},{"id":"c","en":"Gel polish","zh":"凝胶甲油"},{"id":"d","en":"UV gel","zh":"UV凝胶"}],"sourceAnswer":{"en":"Gel polish","zh":"凝胶甲油"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q128"}],"reviewReason":{"en":"The source says gel polish protects color without a UV lamp. Gel polish requires the matching UV or LED curing lamp, so the key is chemically incorrect.","zh":"原题说 gel polish 不用 UV 灯也能保护颜色。凝胶甲油需要配套的 UV 或 LED 固化灯，所以这个答案在化学上是错的。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Light Curing","printedPage":"370-376","pdfPage":394}]},{"id":"practice-nail-test-q129","question":{"en":"What causes permanent skin damage that is most visible?","zh":"什么会导致最明显的永久性皮肤损伤？"},"choices":[{"id":"a","en":"Monomer","zh":"单体液"},{"id":"b","en":"Primer","zh":"底剂"},{"id":"c","en":"Polymer","zh":"聚合物粉"},{"id":"d","en":"Acetone","zh":"丙酮"}],"sourceAnswer":{"en":"Polymer","zh":"聚合物粉"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q129"}],"reviewReason":{"en":"The source keys Polymer for permanent visible skin damage. This is unsupported and conflicts with the textbook\'s skin-damage guidance; no reliable correction can be inferred from the prompt.","zh":"原题把 Polymer 当成造成明显永久皮肤损伤的原因。这没有依据，也和教材的皮肤损伤说明冲突；从题目无法可靠推出正确改法。"},"authorityRefs":[]},{"id":"practice-nail-test-q130","question":{"en":"What movement is combined with a gliding motion during a foot massage?","zh":"足部按摩中与滑动动作结合的手法叫什么？"},"choices":[{"id":"a","en":"Tapotement","zh":"叩击法"},{"id":"b","en":"Effleurage","zh":"轻抚法"},{"id":"c","en":"Deep tissue massage","zh":"深层组织按摩"},{"id":"d","en":"Joint relaxer Movement","zh":"关节放松动作"}],"sourceAnswer":{"en":"Effleurage","zh":"轻抚法"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q130"}],"reviewReason":{"en":"Effleurage is itself a gliding/stroking massage movement. The phrase \'combined with a gliding motion\' does not uniquely define it.","zh":"effleurage（轻抚法）本身就是滑动、抚过的按摩动作。“结合滑动动作”并不能唯一定义它。"},"authorityRefs":[]},{"id":"practice-nail-test-q131","question":{"en":"When applying acrylic powder, what is created at the brush tip?","zh":"涂水晶粉时，刷头会形成什么？"},"choices":[{"id":"a","en":"A flat film of liquid","zh":"一层平坦液膜"},{"id":"b","en":"A dry patch of powder","zh":"一块干燥粉末"},{"id":"c","en":"A rounded bead of product forms at the brush tip","zh":"刷头会形成一个圆润的产品珠"},{"id":"d","en":"A thin string of product","zh":"一条细长的产品丝"}],"sourceAnswer":{"en":"A rounded bead of product forms at the brush tip","zh":"刷头会形成一个圆润的产品珠"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q131"}],"reviewReason":{"en":"The answer describes a product bead, while the stem/distractor structure was extracted as a tool question. It needs question-specific visual/procedural authoring.","zh":"答案描述的是产品粉珠，但题目和干扰项被提取成了工具题。这道题需要按具体视觉或操作重新编写。"},"authorityRefs":[]},{"id":"practice-nail-test-q133","question":{"en":"When using an electric nail file, what is most important for the technician\'s safety?","zh":"使用电动磨甲机时，对技师安全最重要的是什么？"},"choices":[{"id":"a","en":"Use the file at maximum speed","zh":"以最高速度使用磨甲机"},{"id":"b","en":"Work without a dust mask","zh":"不戴防尘口罩操作"},{"id":"c","en":"Using personal protective equipment","zh":"使用个人防护设备"},{"id":"d","en":"Hold the client\'s hand too tightly","zh":"过度用力握住顾客的手"}],"sourceAnswer":{"en":"Using personal protective equipment","zh":"使用个人防护设备"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q133"}],"reviewReason":{"en":"\'Using personal protective equipment\' is too broad to be the unique answer to a most-important safety item.","zh":"“使用个人防护装备”太宽，不能作为“最重要安全事项”的唯一答案。"},"authorityRefs":[]},{"id":"practice-nail-test-q140","question":{"en":"What part of the nail protects against bacterial infection?","zh":"指甲的哪一部分可以防止细菌感染？"},"choices":[{"id":"a","en":"Eponychium","zh":"甲上皮"},{"id":"b","en":"Nail matrix","zh":"甲母质"},{"id":"c","en":"The nail bed","zh":"甲床"},{"id":"d","en":"Nail body","zh":"甲体"}],"sourceAnswer":{"en":"The nail bed","zh":"甲床"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q140"}],"reviewReason":{"en":"The source keys nail bed as the part that protects against bacterial infection. The textbook assigns the seal/barrier role at the free edge to the hyponychium, so this key is not safe to teach.","zh":"原题把 nail bed（甲床）说成防止细菌感染的部位。教材把游离缘的封闭/屏障作用归于 hyponychium（甲下皮），所以这个答案不适合教学。"},"authorityRefs":[]},{"id":"practice-nail-test-q141","question":{"en":"Which tools should be cleaned and dried before being placed in a UV sterilizing cabinet?","zh":"哪些工具在放入紫外线灭菌柜前应清洁并干燥？"},"choices":[{"id":"a","en":"Tools wiped with a dry towel","zh":"只用干毛巾擦拭的工具"},{"id":"b","en":"Single-use porous tools","zh":"一次性多孔工具"},{"id":"c","en":"Tools disinfected to hospital standards","zh":"已按医院标准消毒的工具"},{"id":"d","en":"Tools rinsed with water only","zh":"只用水冲洗的工具"}],"sourceAnswer":{"en":"Tools disinfected to hospital standards","zh":"已按医院标准消毒的工具"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q141"}],"reviewReason":{"en":"The source treats a UV cabinet as a sterilizer after hospital-level disinfection. UV cabinets are not a substitute for required cleaning and EPA-registered disinfection, so this wording is unsafe.","zh":"原题把紫外线柜子当成医院级消毒之后的灭菌器。紫外线柜不能代替必须的清洁和 EPA 注册消毒，所以这句不安全。"},"authorityRefs":[]},{"id":"practice-nail-test-q142","question":{"en":"If a client is allergic to acrylic liquid, what service should be recommended?","zh":"如果顾客对水晶甲液体过敏，应推荐什么服务？"},"choices":[{"id":"a","en":"UV Gel","zh":"UV凝胶"},{"id":"b","en":"Gel polish","zh":"凝胶甲油"},{"id":"c","en":"Builder gel","zh":"建构凝胶"},{"id":"d","en":"Oligomer","zh":"低聚物"}],"sourceAnswer":{"en":"UV Gel","zh":"UV凝胶"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q142"}],"reviewReason":{"en":"Recommending UV gel for an acrylic-liquid allergy is unsafe because both systems may contain related methacrylates that can trigger the same allergy.","zh":"对丙烯酸液体过敏却推荐 UV 凝胶是不安全的，因为两套产品都可能含有相关的 methacrylates，会引发同样的过敏。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Product Allergies","printedPage":"117-120","pdfPage":141}]},{"id":"practice-nail-test-q143","question":{"en":"What is the primer for acrylic nails?","zh":"水晶甲的底剂是什么？"},"choices":[{"id":"a","en":"Acid methacrylic (primer)","zh":"甲基丙烯酸（底剂）"},{"id":"b","en":"Nail dehydrator","zh":"甲面脱水剂"},{"id":"c","en":"Nail adhesive","zh":"美甲粘合剂"},{"id":"d","en":"Non-acid primer","zh":"无酸底剂"}],"sourceAnswer":{"en":"Acid methacrylic (primer)","zh":"甲基丙烯酸（底剂）"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q143"}],"reviewReason":{"en":"The source says acrylic primer is methacrylic acid. Acid-based primers may contain methacrylic acid, but nonacid and acid-free primers also exist, so the generic statement is false.","zh":"原题说丙烯酸底涂就是 methacrylic acid（甲基丙烯酸）。酸性底涂可能含这种酸，但也有非酸和无酸底涂，所以这句笼统说法是错的。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Primers","printedPage":"117-118","pdfPage":141}]},{"id":"practice-nail-test-q144","question":{"en":"The gliding technique combined with tapping is called?","zh":"滑动手法与拍打结合叫什么？"},"choices":[{"id":"a","en":"Joint relaxer Movement","zh":"关节放松动作"},{"id":"b","en":"Petrissage","zh":"揉捏法"},{"id":"c","en":"Effeurage","zh":"轻抚法"},{"id":"d","en":"Deep tissue massage","zh":"深层组织按摩"}],"sourceAnswer":{"en":"Effeurage","zh":"轻抚法"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q144"}],"reviewReason":{"en":"The stem combines gliding with tapping but keys a misspelled effleurage. Effleurage is gliding; tapping is tapotement, so two different movements are mixed together.","zh":"题目把滑动和轻拍混在一起，原题答案还是拼错的 effleurage。effleurage 是滑动，轻拍是 tapotement，两种手法被混成一题。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Manicuring - Massage Movements","printedPage":"162","pdfPage":186}]},{"id":"practice-nail-test-q150","question":{"en":"What term refers to efforts to prevent growth?","zh":"哪个术语指防止生长的努力？"},"choices":[{"id":"a","en":"Immunity","zh":"免疫力"},{"id":"b","en":"Infection","zh":"感染"},{"id":"c","en":"Sanitation","zh":"清洁/卫生处理"},{"id":"d","en":"Cleaning","zh":"清洁"}],"sourceAnswer":{"en":"Immunity","zh":"免疫力"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q150"}],"reviewReason":{"en":"The stem \'efforts to prevent growth\' does not define immunity, the keyed answer. The intended concept cannot be recovered reliably from the source wording.","zh":"题目“阻止生长的努力”并不能定义 immunity（免疫），也就是原题答案。从原文无法可靠还原想考的概念。"},"authorityRefs":[]},{"id":"practice-nail-test-q152","question":{"en":"If a client has bitten nails and wants to apply acrylic nails, where should the technician apply them?","zh":"如果顾客咬指甲并想做水晶甲，技师应把它们贴在哪里？"},"choices":[{"id":"a","en":"Base of the nail","zh":"指甲基部"},{"id":"b","en":"From the nail base to the tip","zh":"从甲根到甲尖"},{"id":"c","en":"The arch of the nail","zh":"指甲的拱形处"},{"id":"d","en":"At the point of attachment","zh":"贴在附着点"}],"sourceAnswer":{"en":"At the point of attachment","zh":"贴在附着点"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q152"}],"reviewReason":{"en":"The instruction to apply acrylic \'at the point of attachment\' does not identify a safe location or procedure for a bitten nail and cannot support one unique answer.","zh":"原题说在“附着点”上丙烯酸，并没有说明咬甲时的安全位置或步骤，也不能支持唯一答案。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Tips - Application on Bitten Nails","printedPage":"252-260","pdfPage":276}]},{"id":"practice-nail-test-q154","question":{"en":"A client with long, naturally curved nails wants which type of gel?","zh":"顾客有长而自然弯曲的指甲，想要哪种凝胶？"},"choices":[{"id":"a","en":"UV Gel","zh":"UV凝胶"},{"id":"b","en":"Oligomer","zh":"低聚物"},{"id":"c","en":"Builder gel","zh":"建构凝胶"},{"id":"d","en":"Gel polish","zh":"凝胶甲油"}],"sourceAnswer":{"en":"UV Gel","zh":"UV凝胶"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q154"}],"reviewReason":{"en":"Naturally curved, long nails do not uniquely require UV gel. Product choice depends on the client\'s goal and nail condition, which the stem does not provide.","zh":"天生弯曲的长甲并不必须用 UV 凝胶。产品选择取决于客人目标和甲况，题目没有提供这些信息。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Product Types","printedPage":"370-376","pdfPage":394}]},{"id":"practice-nail-test-q155","question":{"en":"What gel should be applied to a flat, smooth nail?","zh":"平坦、光滑的指甲应使用什么凝胶？"},"choices":[{"id":"a","en":"Builder gel","zh":"建构凝胶"},{"id":"b","en":"UV gel","zh":"UV凝胶"},{"id":"c","en":"Oligomer","zh":"低聚物"},{"id":"d","en":"Gel polish","zh":"凝胶甲油"}],"sourceAnswer":{"en":"Builder gel","zh":"建构凝胶"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q155"}],"reviewReason":{"en":"A flat, smooth nail does not uniquely require builder gel. The desired service and structural need are missing, so several products could be appropriate.","zh":"平整光滑的指甲并不必须用 builder gel。缺少目标服务和结构需求，多种产品都可能合适。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"UV and LED Gels - Building Gels","printedPage":"370-379","pdfPage":394}]},{"id":"practice-nail-test-q160","question":{"en":"Monomer without smell that creates a sticky layer when dry is called?","zh":"无味单体在干燥时形成的黏性层叫什么？"},"choices":[{"id":"a","en":"An uncured layer","zh":"未固化层"},{"id":"b","en":"A dispersion layer","zh":"浮胶层"},{"id":"c","en":"A curing layer","zh":"固化层"},{"id":"d","en":"An inhibition layer","zh":"阻聚层"}],"sourceAnswer":{"en":"A curing layer","zh":"固化层"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q160"}],"reviewReason":{"en":"The source calls the tacky surface left by an odorless monomer a \'curing layer.\' The recognized concept is an inhibition/tacky layer; the keyed term is not reliable.","zh":"原题把无味单体留下的黏层叫做 curing layer。公认概念是 inhibition/tacky layer（抑制层/黏层）；原题术语不可靠。"},"authorityRefs":[]},{"id":"practice-nail-test-q161","question":{"en":"The organisms that cause infections in living beings are called?","zh":"导致生物感染的有机体叫什么？"},"choices":[{"id":"a","en":"Pathogenic organisms","zh":"致病微生物"},{"id":"b","en":"Nonpathogenic organisms","zh":"非致病性微生物"},{"id":"c","en":"Infectious organisms","zh":"感染性有机体"},{"id":"d","en":"Saprophytes","zh":"腐生菌"}],"sourceAnswer":{"en":"Infectious organisms","zh":"感染性有机体"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q161"}],"reviewReason":{"en":"The textbook term is pathogenic organisms. The source key \'infectious organisms\' is not the expected exam term.","zh":"教材术语是 pathogenic organisms（致病生物）。原题答案 infectious organisms 不是预期的考试用语。"},"authorityRefs":[]},{"id":"practice-nail-test-q165","question":{"en":"Which type of artificial nails is easiest to remove?","zh":"哪种人工指甲最容易卸除？"},"choices":[{"id":"a","en":"Nail wraps","zh":"指甲包裹系统"},{"id":"b","en":"Full-cover nails","zh":"全贴甲片"},{"id":"c","en":"Acrylic overlays","zh":"丙烯酸覆盖层"},{"id":"d","en":"Sculptured nails","zh":"雕塑甲"}],"sourceAnswer":{"en":"Full-cover nails","zh":"全贴甲片"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q165"}],"reviewReason":{"en":"Full-cover nails are not universally the easiest artificial nails to remove; removal depends on the adhesive and product chemistry.","zh":"全贴甲并不是普遍最容易卸除的假甲；卸除难度取决于胶水和产品化学。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Tips - Full-Coverage Tips and Removal","printedPage":"252-267","pdfPage":276}]},{"id":"practice-nail-test-q171","question":{"en":"What is the main ingredient in primer?","zh":"底剂的主要成分是什么？"},"choices":[{"id":"a","en":"Nitrocellulose","zh":"硝化纤维素"},{"id":"b","en":"Methacrylic Acid","zh":"甲基丙烯酸"},{"id":"c","en":"Cyanoacrylate","zh":"氰基丙烯酸酯"},{"id":"d","en":"Oligomer","zh":"低聚物"}],"sourceAnswer":{"en":"Methacrylic Acid","zh":"甲基丙烯酸"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q171"}],"reviewReason":{"en":"The source says methacrylic acid is the main ingredient in primer. This applies only to acid-based primers; the textbook describes nonacid and acid-free primers as well.","zh":"原题说 methacrylic acid 是底涂的主要成分。这只适用于酸性底涂；教材也写了非酸和无酸底涂。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Primers","printedPage":"117-118","pdfPage":141}]},{"id":"practice-nail-test-q175","question":{"en":"How should a foot bath be disinfected?","zh":"足浴应如何消毒？"},"choices":[{"id":"a","en":"Hospital-grade disinfection","zh":"医院级消毒"},{"id":"b","en":"Rinse off the dirty water","zh":"冲掉脏水"},{"id":"c","en":"Liquid disinfectant","zh":"液体消毒剂"},{"id":"d","en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"}],"sourceAnswer":{"en":"Rinse off the dirty water","zh":"冲掉脏水"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q175"}],"reviewReason":{"en":"Rinsing out dirty water alone does not disinfect a foot bath. Shipping this keyed answer would teach an unsafe infection-control procedure.","zh":"只冲掉脏水并不能给足浴盆消毒。如果把这个原题答案当作正确答案，会教出不安全的感染控制步骤。"},"authorityRefs":[]},{"id":"practice-nail-test-q187","question":{"en":"How long does it take to complete a full nail technician course?","zh":"完成完整美甲技师课程需要多长时间？"},"choices":[{"id":"a","en":"9 months","zh":"9个月"},{"id":"b","en":"3 months","zh":"3个月"},{"id":"c","en":"6 months","zh":"6个月"},{"id":"d","en":"12 months","zh":"12个月"}],"sourceAnswer":{"en":"6 months","zh":"6个月"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q187"}],"reviewReason":{"en":"Course length is jurisdiction- and schedule-dependent; the source gives six months without identifying a program or licensing jurisdiction.","zh":"课程时长取决于管辖区和课程安排；原题写六个月，却没有说明是哪个项目或哪个执照地区。"},"authorityRefs":[]},{"id":"practice-nail-test-q189","question":{"en":"What is a chemical reaction that accelerates?","zh":"加速化学反应的物质是什么？"},"choices":[{"id":"a","en":"A catalyst","zh":"催化剂"},{"id":"b","en":"An inhibitor","zh":"抑制剂"},{"id":"c","en":"A monomer","zh":"单体"},{"id":"d","en":"A solvent","zh":"溶剂"}],"sourceAnswer":{"en":"A catalyst","zh":"催化剂"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q189"}],"reviewReason":{"en":"The stem asks for a chemical reaction that accelerates but keys catalyst. A catalyst is a substance that speeds a reaction, not a reaction itself, so the grammar changes the scientific meaning.","zh":"题目问的是会加速的化学反应，原题答案却是 catalyst（催化剂）。催化剂是加快反应的物质，不是反应本身，语法改变了科学含义。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Catalysts","printedPage":"123","pdfPage":147}]},{"id":"practice-nail-test-q196","question":{"en":"What angle should an electric file be held when working next to the nail?","zh":"在靠近指甲工作时，电动磨甲机应保持什么角度？"},"choices":[{"id":"a","en":"90 degrees","zh":"90度"},{"id":"b","en":"At a 45-degree angle to the nail surface","zh":"与甲面成45度角"},{"id":"c","en":"30 degrees","zh":"30度"},{"id":"d","en":"60 degrees","zh":"60度"}],"sourceAnswer":{"en":"At a 45-degree angle to the nail surface","zh":"与甲面成45度角"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q196"}],"reviewReason":{"en":"The phrase \'working next to the nail\' does not identify the sidewall, skin, or enhancement surface, so the keyed 45-degree electric-file angle cannot be applied safely.","zh":"“在指甲旁边操作”没有说明是侧壁、皮肤还是增强甲表面，所以原题的 45 度电动磨甲角度不能安全套用。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Electric Filing - Safe Angles","printedPage":"240-248","pdfPage":264}]},{"id":"practice-nail-test-q197","question":{"en":"If a client’s nail tip is cracked in the middle, what is likely the issue?","zh":"如果顾客的甲片在中间开裂，可能是什么问题？"},"choices":[{"id":"a","en":"Too much adhesive used","zh":"使用了过多黏合剂"},{"id":"b","en":"The lamp was on too long","zh":"灯照时间过长"},{"id":"c","en":"Incorrect polymer ratio,","zh":"聚合物比例不正确，"},{"id":"d","en":"The product overflowed onto the skin","zh":"产品溢到了皮肤上"}],"sourceAnswer":{"en":"Too much adhesive used","zh":"使用了过多黏合剂"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q197"}],"reviewReason":{"en":"The source uniquely blames too much adhesive for a cracked tip. Cracks can result from sizing, fit, impact, structure, or adhesive use, and the stem gives no diagnostic evidence.","zh":"原题把甲片中间裂纹只归咎于胶水太多。裂纹也可能来自尺寸、贴合、撞击、结构或胶水用法，题目没有给出判断依据。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Tips - Adhesive Application and Fit","printedPage":"252-260","pdfPage":276}]},{"id":"practice-nail-test-q200","question":{"en":"What material is the sharpest on an electric file?","zh":"电动磨甲机上最锋利的材料是什么？"},"choices":[{"id":"a","en":"Sanding band","zh":"砂圈"},{"id":"b","en":"Diamond","zh":"金刚石"},{"id":"c","en":"Carbide (carbide bit)","zh":"碳化物（碳化物磨头）"},{"id":"d","en":"Ceramic","zh":"陶瓷"}],"sourceAnswer":{"en":"Carbide (carbide bit)","zh":"碳化物（碳化物磨头）"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q200"}],"reviewReason":{"en":"The source calls carbide the \'sharpest material\' for an electric file. Bit cutting action depends on design and grit; carbide, diamond, ceramic, and sanding bands are not ranked by one universal sharpness rule.","zh":"原题把 carbide 说成电动磨甲机“最锋利的材料”。切削效果取决于设计和砂目；碳化钨、金刚石、陶瓷和砂圈不能用一条通用锋利规则排序。"},"authorityRefs":[]},{"id":"practice-nail-test-q202","question":{"en":"After finishing a service, what is not correct?","zh":"完成服务后，哪项是不正确的？"},"choices":[{"id":"a","en":"Put on gloves and ask the client to wash their hands","zh":"戴上手套并请顾客洗手"},{"id":"b","en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"},{"id":"c","en":"Liquid disinfectant","zh":"液体消毒剂"},{"id":"d","en":"Hospital-grade disinfection","zh":"医院级消毒"}],"sourceAnswer":{"en":"Disinfect the client’s hands","zh":"给顾客的双手消毒"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q202"}],"reviewReason":{"en":"Disinfecting a client\'s hands after a service is not inherently the single incorrect action. The stem supplies no complete post-service sequence or useful unique contrast.","zh":"服务后给客人手部消毒，本身不一定就是唯一错误做法。题目没有完整的服务后步骤，也没有有用的唯一对比。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Post-Service Procedure","printedPage":"172-181","pdfPage":196}]},{"id":"practice-nail-test-q203","question":{"en":"Which U.S. agency prohibits methyl methacrylate (MMA) in nail products?","zh":"美国哪个机构禁止在美甲产品中使用甲基丙烯酸甲酯（MMA）？"},"choices":[{"id":"a","en":"EPA","zh":"美国环境保护署（EPA）"},{"id":"b","en":"FDA","zh":"美国食品药品监督管理局（FDA）"},{"id":"c","en":"OSHA","zh":"美国职业安全与健康管理局（OSHA）"},{"id":"d","en":"CDC","zh":"疾病控制与预防中心（CDC）"}],"sourceAnswer":{"en":"FDA","zh":"美国食品药品监督管理局（FDA）"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q203"}],"reviewReason":{"en":"The source says the FDA prohibits MMA in nail products. FDA enforcement history and state bans are more nuanced; the agency has not issued the simple universal prohibition claimed.","zh":"原题说 FDA 禁止美甲产品使用 MMA。FDA 执法历史和各州禁令更复杂；该机构并没有发出原题所说的那种简单、全面禁止。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Methyl Methacrylate Monomer","printedPage":"124-125","pdfPage":148}]},{"id":"practice-nail-test-q204","question":{"en":"When applying acrylic nails, where should the nail tip be placed?","zh":"做水晶甲时，甲片应放在哪里？"},"choices":[{"id":"a","en":"Base of the nail","zh":"指甲基部"},{"id":"b","en":"The arch of the nail","zh":"指甲的拱形处"},{"id":"c","en":"From the nail base to the tip","zh":"从甲根到甲尖"},{"id":"d","en":"At the point of attachment","zh":"贴在附着点"}],"sourceAnswer":{"en":"The arch of the nail","zh":"指甲的拱形处"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"q204"}],"reviewReason":{"en":"The source says a nail tip is placed at the arch of the nail. Tips attach at their contact area and stop point; the arch is not the universal placement location.","zh":"原题说甲片放在指甲的 arch（拱起处）。甲片应贴在接触区和停止点；拱起处不是通用放置位置。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Tips - Application and Contact Area","printedPage":"252-260","pdfPage":276}]},{"id":"practice-nail-test-n002","question":{"en":"Cleanse and sanitize a customer’s nails before applying artificial nails because","zh":"为什么在贴人工指甲前要清洁并卫生处理顾客的指甲？"},"choices":[{"id":"a","en":"Relaxation","zh":"放松"},{"id":"b","en":"To Prevent Fungus","zh":"预防真菌"},{"id":"c","en":"To soften the cuticles","zh":"软化甲小皮"},{"id":"d","en":"To soften the skin","zh":"软化皮肤"}],"sourceAnswer":{"en":"To Prevent Fungus","zh":"预防真菌"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n002"}],"reviewReason":{"en":"Cleaning before an enhancement helps remove many contaminants but does not guarantee prevention of fungus. The source teaches an overconfident medical outcome.","zh":"做增强甲前清洁有助于去掉许多污染物，但不能保证防止真菌。原题把这个医疗结果说得过于肯定。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Preparing for Adhesion","printedPage":"119","pdfPage":143}]},{"id":"practice-nail-test-n003","question":{"en":"The ingredient in Top Coat is","zh":"Top Coat的成分是什么？"},"choices":[{"id":"a","en":"Polyester Resin","zh":"聚酯树脂"},{"id":"b","en":"Non-acetone","zh":"非丙酮卸除剂"},{"id":"c","en":"Nail polish remover","zh":"卸甲液"},{"id":"d","en":"Nitrocellulose","zh":"硝化纤维素"}],"sourceAnswer":{"en":"Polyester Resin","zh":"聚酯树脂"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n003"}],"reviewReason":{"en":"The source says polyester resin is the ingredient in every top coat. Top-coat formulas vary and the textbook does not support one universal resin ingredient.","zh":"原题说每一种亮油都含 polyester resin。亮油配方各不相同，教材并不支持只有这一种树脂成分。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Product Chemistry - Nail Coatings","printedPage":"125-126","pdfPage":149}]},{"id":"practice-nail-test-n004","question":{"en":"Which nail disease involves inflammation of the matrix and may include pus, redness, and swelling?","zh":"哪种指甲疾病涉及甲母质发炎，并可能出现脓液、发红和肿胀？"},"choices":[{"id":"a","en":"Onychophagy","zh":"咬甲癖"},{"id":"b","en":"Onychia","zh":"甲炎"},{"id":"c","en":"Onycholysis","zh":"甲剥离"},{"id":"d","en":"Onychorrhexis","zh":"甲纵裂"}],"sourceAnswer":{"en":"Onychia","zh":"甲炎"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n004"}],"reviewReason":{"en":"The source keys onychia for inflammation with pus, redness, and swelling. Milady defines onychia as matrix inflammation with nail shedding, while pus and surrounding-tissue inflammation point toward paronychia.","zh":"原题把有脓、红、肿的炎症叫 onychia。Milady 把 onychia 定义为甲母质炎症并伴随脱甲；脓液和周围组织炎症更指向 paronychia（甲沟炎）。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Diseases - Onychia and Paronychia","printedPage":"109","pdfPage":133}]},{"id":"practice-nail-test-n009","question":{"en":"What kind of brush works best for gel nails as blending and shaping","zh":"哪种刷子最适合凝胶甲的融合和塑形？"},"choices":[{"id":"a","en":"Round acrylic brush","zh":"圆形丙烯酸刷"},{"id":"b","en":"Oval gel brush","zh":"椭圆形凝胶刷"},{"id":"c","en":"Small Flat synthetic Brush","zh":"小号扁平合成刷"},{"id":"d","en":"Detail liner brush","zh":"细节勾线刷"}],"sourceAnswer":{"en":"Small Flat synthetic Brush","zh":"小号扁平合成刷"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n009"}],"reviewReason":{"en":"More than one synthetic gel-brush shape can blend and shape gel. The stem gives no service detail that makes a small flat brush uniquely correct.","zh":"不止一种合成凝胶笔形状可以推匀和塑形。题目没有服务细节证明只有小扁笔才正确。"},"authorityRefs":[]},{"id":"practice-nail-test-n011","question":{"en":"It will be helpful to a student’s success to develop a","zh":"培养什么会有助于学生成功？"},"choices":[{"id":"a","en":"A negative attitude","zh":"消极态度"},{"id":"b","en":"Unreliable attendance","zh":"出勤不可靠"},{"id":"c","en":"Pleasing Personality","zh":"讨人喜欢的个性"},{"id":"d","en":"Poor hygiene","zh":"卫生习惯不佳"}],"sourceAnswer":{"en":"Pleasing Personality","zh":"讨人喜欢的个性"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n011"}],"reviewReason":{"en":"The keyed \'pleasing personality\' is subjective, culturally loaded, and not a measurable requirement for student success. It cannot support fair educational review.","zh":"原题答案“讨人喜欢的性格”很主观，带有文化偏见，也不是可测量的学生成功条件。它无法支持公平的教学审核。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Life Skills - Personality and Success","printedPage":"3-15","pdfPage":498}]},{"id":"practice-nail-test-n013","question":{"en":"What is the nail condition that may receive a manicure","zh":"哪种指甲状况可以接受手部美甲护理？"},"choices":[{"id":"a","en":"Onychophagy","zh":"咬甲癖"},{"id":"b","en":"Onychia","zh":"甲炎"},{"id":"c","en":"Onychauxis","zh":"甲肥厚（onychauxis）"},{"id":"d","en":"Onycholysis","zh":"甲剥离"}],"sourceAnswer":{"en":"Onychophagy","zh":"咬甲癖"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n013"}],"reviewReason":{"en":"More than one noninfectious nail condition may receive a carefully adapted manicure. The stem does not make onychophagy the only safe answer.","zh":"多种非传染性甲况都可以接受谨慎调整后的美甲。题目并不能证明只有 onychophagy（咬甲）才是安全答案。"},"authorityRefs":[]},{"id":"practice-nail-test-n015","question":{"en":"The only true living part of the nail is the","zh":"指甲唯一真正有生命的部分是什么？"},"choices":[{"id":"a","en":"Eponychium","zh":"甲上皮"},{"id":"b","en":"Nail Root","zh":"甲根"},{"id":"c","en":"Nail mantle","zh":"甲套"},{"id":"d","en":"Nail body","zh":"甲体"}],"sourceAnswer":{"en":"Nail Root","zh":"甲根"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n015"}],"reviewReason":{"en":"The source calls the nail root the only true living part, but the matrix is the living growth tissue and other tissues in the nail unit are also living. The absolute wording is inaccurate.","zh":"原题说甲根是唯一真正的活组织，但 matrix（甲母质）才是生长活组织，甲单位里还有其他活组织。这种绝对说法不准确。"},"authorityRefs":[]},{"id":"practice-nail-test-n018","question":{"en":"Which is an example of a general infection?","zh":"哪一项属于全身性感染的例子？"},"choices":[{"id":"a","en":"Blood Poisoning","zh":"血液中毒"},{"id":"b","en":"Bruised nail","zh":"受伤淤青的指甲"},{"id":"c","en":"Localized boil","zh":"局部疖肿"},{"id":"d","en":"Hangnail","zh":"倒刺"}],"sourceAnswer":{"en":"Blood Poisoning","zh":"血液中毒"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n018"}],"reviewReason":{"en":"The key uses the outdated lay phrase \'blood poisoning\' as a general infection. This may refer to sepsis or bloodstream infection, which are distinct medical conditions.","zh":"原题用过时俗语 blood poisoning（血液中毒）当作一般感染。它可能指 sepsis 或血液感染，这些是不同的医学情况。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Local and Systemic Infections","printedPage":"106-109","pdfPage":601}]},{"id":"practice-nail-test-n020","question":{"en":"A quaternary ammonium compounds 1,000 part per million (ppm) is commonly used as a disinfectant solution is also called","zh":"浓度为1000 ppm的季铵化合物常用作消毒液，也称为什么？"},"choices":[{"id":"a","en":"Wet Sanitizer","zh":"湿式卫生处理剂"},{"id":"b","en":"Dry sanitizer","zh":"干式消毒器"},{"id":"c","en":"Autoclave","zh":"高压蒸汽灭菌器"},{"id":"d","en":"UV cabinet","zh":"紫外线柜"}],"sourceAnswer":{"en":"Wet Sanitizer","zh":"湿式卫生处理剂"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n020"}],"reviewReason":{"en":"The source calls a 1,000 ppm quaternary ammonium solution a wet sanitizer. Product concentration and contact time must follow the current label; this old generic rule is unsafe.","zh":"原题把 1,000 ppm 季铵盐溶液叫做湿式消毒剂。产品浓度和接触时间必须遵循现行标签；这条旧的笼统规则不安全。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Quaternary Ammonium Compounds","printedPage":"120-123","pdfPage":615}]},{"id":"practice-nail-test-n021","question":{"en":"Sharp metallic instruments may be sanitized with","zh":"尖锐金属器械可用什么进行清洁/卫生处理？"},"choices":[{"id":"a","en":"Sweat and sebum (oil)","zh":"汗液和皮脂（油脂）"},{"id":"b","en":"Cuticle oil","zh":"甲小皮油"},{"id":"c","en":"70% Methyl Alcohol","zh":"70%甲醇"},{"id":"d","en":"Disinfectant","zh":"消毒剂"}],"sourceAnswer":{"en":"70% Methyl Alcohol","zh":"70%甲醇"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n021"}],"reviewReason":{"en":"The source recommends 70 percent methyl alcohol for sharp tools. Current salon practice requires cleaning and an EPA-registered disinfectant; methanol is toxic and not an acceptable generic implement disinfectant.","zh":"原题建议用 70% 甲醇处理锋利工具。现行沙龙做法要求先清洁，再用 EPA 注册消毒剂；甲醇有毒，不能当作通用工具消毒剂。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Disinfecting Implements","printedPage":"138-140","pdfPage":633}]},{"id":"practice-nail-test-n023","question":{"en":"The skin under the nail’s free edge is hyponychium and the skin that surrounds the nail area is called","zh":"指甲游离缘下面的皮肤是甲下皮，围绕指甲区域的皮肤叫什么？"},"choices":[{"id":"a","en":"Nail body","zh":"甲体"},{"id":"b","en":"Perionychium","zh":"甲周皮"},{"id":"c","en":"Nail bed","zh":"甲床"},{"id":"d","en":"Nail mantle","zh":"甲套"}],"sourceAnswer":{"en":"Perionychium","zh":"甲周皮"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n023"}],"reviewReason":{"en":"The source uses perionychium as the skin surrounding the nail. Current textbook terminology identifies specific nail folds, eponychium, and hyponychium and does not use this term.","zh":"原题用 perionychium 表示指甲周围皮肤。现行教材使用具体的甲皱襞、eponychium 和 hyponychium，并不使用这个词。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Structure - Nail Folds and Surrounding Skin","printedPage":"99-102","pdfPage":123}]},{"id":"practice-nail-test-n026","question":{"en":"An inflammatory condition of the tissues surrounding the nail is known as","zh":"围绕指甲组织的炎症状况称为什么？"},"choices":[{"id":"a","en":"Onychauxis","zh":"甲肥厚（onychauxis）"},{"id":"b","en":"Onychoptosis","zh":"甲脱落症"},{"id":"c","en":"Onychia","zh":"甲炎"},{"id":"d","en":"Onychorrhexis","zh":"甲纵裂"}],"sourceAnswer":{"en":"Onychoptosis","zh":"甲脱落症"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n026"}],"reviewReason":{"en":"The source keys onychoptosis for inflamed tissue surrounding the nail. The recognized term is paronychia; onychoptosis means shedding or falling off of the nail.","zh":"原题把指甲周围组织发炎叫做 onychoptosis。公认术语是 paronychia（甲沟炎）；onychoptosis 指指甲脱落。"},"authorityRefs":[]},{"id":"practice-nail-test-n027","question":{"en":"In case of a small cut, one of the following may be sued","zh":"小割伤时，可以使用以下哪一种？"},"choices":[{"id":"a","en":"Sweat and sebum (oil)","zh":"汗液和皮脂（油脂）"},{"id":"b","en":"Full-cover nails","zh":"全贴甲片"},{"id":"c","en":"3% hydrogen peroxide","zh":"3%过氧化氢"},{"id":"d","en":"Exfoliants","zh":"去角质产品"}],"sourceAnswer":{"en":"3% hydrogen peroxide","zh":"3%过氧化氢"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n027"}],"reviewReason":{"en":"The source recommends 3 percent hydrogen peroxide for a small cut. Current exposure procedures use washing, antiseptic offered to the client, and a bandage; peroxide is not the first universal rule.","zh":"原题建议小伤口用 3% 过氧化氢。现行暴露处理是冲洗、向客人提供防腐剂并包扎；过氧化氢不是第一条通用规则。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Procedure 5-3: Client Injury","printedPage":"141-143","pdfPage":636}]},{"id":"practice-nail-test-n028","question":{"en":"How should a metal cuticle pusher be used?","zh":"应如何使用金属甲小皮推？"},"choices":[{"id":"a","en":"Flat, with gentle pressure, on a most nail bed","zh":"平放，轻柔施压，在湿润的甲床上使用"},{"id":"b","en":"Under the free edge with the point","zh":"用尖端伸到游离缘下方"},{"id":"c","en":"At a steep angle with firm pressure","zh":"以陡角度用力施压"},{"id":"d","en":"On dry tissue with a sawing motion","zh":"在干燥组织上来回锯动"}],"sourceAnswer":{"en":"Flat, with gentle pressure, on a most nail bed","zh":"平放，轻柔施压，在湿润的甲床上使用"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n028"}],"reviewReason":{"en":"The source answer is damaged (\'on a most nail bed\') and incorrectly places a metal pusher on the nail bed. A pusher is used gently and nearly flat on the nail plate, not living nail-bed tissue.","zh":"原题答案损坏（on a most nail bed），还错误地把金属推棒放在甲床上。推棒应几乎放平，轻轻用在甲板上，而不是活的甲床组织上。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Manicuring - Metal Pusher Use","printedPage":"165-167","pdfPage":189}]},{"id":"practice-nail-test-n031","question":{"en":"Manicure implements will be disinfected when immersed in 70% ethyl alcohol for a period of","zh":"手部美甲护理工具浸泡在70%乙醇中多久会被消毒？"},"choices":[{"id":"a","en":"60 seconds","zh":"60秒"},{"id":"b","en":"30 seconds","zh":"30秒"},{"id":"c","en":"20 seconds","zh":"20秒"},{"id":"d","en":"10 minutes","zh":"10分钟"}],"sourceAnswer":{"en":"10 minutes","zh":"10分钟"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n031"}],"reviewReason":{"en":"The source teaches immersion in 70 percent ethyl alcohol for ten minutes as implement disinfection. This is outdated and not a safe general salon disinfection rule.","zh":"原题把工具浸入 70% 乙醇十分钟当作消毒。这已经过时，不是安全的通用沙龙消毒规则。"},"authorityRefs":[]},{"id":"practice-nail-test-n032","question":{"en":"The deep fold of the skin where the nail root is lodged is known as","zh":"甲根所在的深层皮肤褶皱叫什么？"},"choices":[{"id":"a","en":"Free edge","zh":"游离缘"},{"id":"b","en":"Nail matrix","zh":"甲母质"},{"id":"c","en":"Nail Mantle","zh":"甲套"},{"id":"d","en":"Hyponychium","zh":"甲下皮"}],"sourceAnswer":{"en":"Nail Mantle","zh":"甲套"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n032"}],"reviewReason":{"en":"The source uses the older term nail mantle for the deep fold holding the root. Current terminology uses proximal nail fold and matrix-area structures.","zh":"原题用旧词 nail mantle 表示包住甲根的深褶。现行术语使用 proximal nail fold（近端甲皱襞）和甲母质区域结构。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Structure - Proximal Nail Fold and Matrix","printedPage":"99-102","pdfPage":123}]},{"id":"practice-nail-test-n033","question":{"en":"The movement of the hand is controlled by","zh":"手部运动由什么控制？"},"choices":[{"id":"a","en":"Flexor muscle","zh":"屈肌"},{"id":"b","en":"Supinator muscle","zh":"旋后肌"},{"id":"c","en":"Supinator’s, flexors, extensors, All of the Above","zh":"旋后肌、屈肌、伸肌，以上全部"},{"id":"d","en":"Adductor muscle","zh":"内收肌"}],"sourceAnswer":{"en":"Supinator’s, flexors, extensors, All of the Above","zh":"旋后肌、屈肌、伸肌，以上全部"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n033"}],"reviewReason":{"en":"The keyed all-of-the-above answer combines several muscles, while the generated alternatives name muscles that each control some hand movement. The stem is not exclusive.","zh":"原题“以上都是”把几块肌肉合在一起，而生成的其他选项也各自控制部分手部运动。题目并没有唯一排他的答案。"},"authorityRefs":[]},{"id":"practice-nail-test-n036","question":{"en":"Another name for cuticle is","zh":"甲小皮的另一个名称是什么？"},"choices":[{"id":"a","en":"scarf skin","zh":"死皮"},{"id":"b","en":"Eponychium","zh":"甲上皮"},{"id":"c","en":"Perionychium","zh":"甲周皮"},{"id":"d","en":"Hyponychium","zh":"甲下皮"}],"sourceAnswer":{"en":"scarf skin","zh":"死皮"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n036"}],"reviewReason":{"en":"The source keys the obsolete phrase \'scarf skin\' as another name for cuticle. Current textbook terminology defines cuticle as dead tissue attached to the nail plate and does not use this synonym.","zh":"原题把过时说法 scarf skin 当作 cuticle 的别名。现行教材把 cuticle 定义为附着在甲板上的死组织，并不使用这个同义词。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Structure - Cuticle","printedPage":"101-102","pdfPage":125}]},{"id":"practice-nail-test-n039","question":{"en":"The nail walls are small folds of skin overlapping the sides of the nail","zh":"甲壁是覆盖指甲两侧的小皮肤褶皱，属于什么？"},"choices":[{"id":"a","en":"Eponychium","zh":"甲上皮"},{"id":"b","en":"Nail bed","zh":"甲床"},{"id":"c","en":"Hyponychium","zh":"甲下皮"},{"id":"d","en":"Body","zh":"甲体"}],"sourceAnswer":{"en":"Body","zh":"甲体"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n039"}],"reviewReason":{"en":"The stem defines nail walls but keys \'Body.\' Nail walls are folds of skin overlapping the sides of the nail; the keyed answer does not complete the statement.","zh":"题目定义的是 nail walls（甲侧壁），原题答案却是 Body。甲侧壁是覆盖指甲两侧的皮肤皱褶；这个答案没有把句子补完整。"},"authorityRefs":[]},{"id":"practice-nail-test-n040","question":{"en":"Where is the nail root lodged within the nail mantle?","zh":"甲根位于甲沟内的什么位置？"},"choices":[{"id":"a","en":"Base of the nail","zh":"指甲基部"},{"id":"b","en":"At the free edge","zh":"在游离缘处"},{"id":"c","en":"Under the nail tip","zh":"在甲尖下方"},{"id":"d","en":"Along the sidewall","zh":"沿甲侧壁"}],"sourceAnswer":{"en":"Base of the nail","zh":"指甲基部"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n040"}],"reviewReason":{"en":"The source relies on the outdated nail mantle term and answers only \'base of the nail,\' which is too imprecise to identify root and matrix anatomy.","zh":"原题依赖过时的 nail mantle 术语，答案只有“指甲底部”，太不精确，无法说明甲根和甲母质解剖。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Structure - Matrix and Root Area","printedPage":"99-102","pdfPage":123}]},{"id":"practice-nail-test-n041","question":{"en":"Which structure is not one of the three main parts of the natural nail?","zh":"哪一结构不属于天然指甲的三个主要部分？"},"choices":[{"id":"a","en":"Mantle","zh":"甲套"},{"id":"b","en":"Nail root","zh":"甲根"},{"id":"c","en":"Free edge","zh":"游离缘"},{"id":"d","en":"Nail body","zh":"甲体"}],"sourceAnswer":{"en":"Mantle","zh":"甲套"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n041"}],"reviewReason":{"en":"The question treats mantle as a recognized alternative among three main natural-nail parts. Current textbook anatomy uses more specific structures and does not support this classification.","zh":"题目把 mantle 当成天然甲三个主要部分之一的选项。现行教材解剖使用更具体的结构，并不支持这种分类。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Structure - Major Parts","printedPage":"97-102","pdfPage":121}]},{"id":"practice-nail-test-n042","question":{"en":"Which of the following is not a nail disease","zh":"以下哪项不是指甲疾病？"},"choices":[{"id":"a","en":"Onychophagy","zh":"咬甲癖"},{"id":"b","en":"Leukonychia","zh":"白甲病"},{"id":"c","en":"Verruca","zh":"疣"},{"id":"d","en":"Onychia","zh":"甲炎"}],"sourceAnswer":{"en":"Onychophagy","zh":"咬甲癖"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n042"}],"reviewReason":{"en":"The stem asks which option is not a nail disease, but more than one listed condition can be classified as a disorder or skin condition rather than a nail disease.","zh":"题目问哪一项不是指甲疾病，但列出的情况里，不止一项可归为障碍或皮肤问题，而不是指甲疾病。"},"authorityRefs":[]},{"id":"practice-nail-test-n058","question":{"en":"The main part of the nail is attached to the skin at the tip of the finger which is called","zh":"指甲的主体附着在指尖皮肤上，该部位称为"},"choices":[{"id":"a","en":"Nail bed","zh":"甲床"},{"id":"b","en":"Eponychium","zh":"甲上皮"},{"id":"c","en":"Nail mantle","zh":"甲套"},{"id":"d","en":"Nail Body","zh":"甲体"}],"sourceAnswer":{"en":"Nail Body","zh":"甲体"},"sources":[{"book":"NAIL TEST (EN)","itemRef":"n058"}],"reviewReason":{"en":"The source says the nail body is attached to skin at the fingertip. The nail plate rests on the nail bed and its free edge extends beyond the fingertip, so the keyed wording is anatomically misleading.","zh":"原题说甲体附着在指尖皮肤上。甲板贴在甲床上，游离缘伸出指尖，所以原题措辞在解剖上会误导。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Nail Structure - Nail Plate, Nail Bed, and Free Edge","printedPage":"99-100","pdfPage":123}]},{"id":"practice-theory-update-023","question":{"en":"Metal tools contaminated with blood must be:","zh":"被血液污染的金属工具必须："},"choices":[{"id":"a","en":"Used again immediately","zh":"立即再次使用"},{"id":"b","en":"Rinsed with water","zh":"用水冲洗"},{"id":"c","en":"Properly cleaned and sterilized before reuse","zh":"重复使用前必须正确清洁并灭菌"},{"id":"d","en":"Wiped with a towel","zh":"用毛巾擦拭"}],"sourceAnswer":{"en":"Properly cleaned and sterilized before reuse","zh":"重复使用前必须正确清洁并灭菌"},"sources":[{"book":"NEW UPDATE NAILS THEORY","itemRef":"023"}],"reviewReason":{"en":"The source requires blood-contaminated metal tools to be sterilized before reuse. Milady requires proper cleaning and EPA-registered disinfection; sterilization requirements depend on jurisdiction and equipment.","zh":"原题要求被血液污染的金属工具在再次使用前必须灭菌。Milady 要求正确清洁和 EPA 注册消毒；是否需要灭菌取决于管辖区和设备。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Cleaning and Disinfecting Implements","printedPage":"138-140","pdfPage":633}]},{"id":"practice-theory-update-024","question":{"en":"If you accidentally cut a client and they begin bleeding, the first thing you should do is:","zh":"如果意外割伤客户并开始出血，你首先应该做的是："},"choices":[{"id":"a","en":"Wipe it dry","zh":"擦干"},{"id":"b","en":"Put on gloves","zh":"戴上手套"},{"id":"c","en":"Continue the service","zh":"继续服务"},{"id":"d","en":"Cover it with polish","zh":"用指甲油覆盖"}],"sourceAnswer":{"en":"Put on gloves","zh":"戴上手套"},"sources":[{"book":"NEW UPDATE NAILS THEORY","itemRef":"024"}],"reviewReason":{"en":"The source says putting on gloves is the first action after accidentally cutting a client. Milady Procedure 5-3 says to stop the service immediately before putting on gloves, so the keyed sequence is unsafe to teach as written.","zh":"原题说不小心割伤客人后第一件事是戴手套。Milady 程序 5-3 说应先立即停止服务，再戴手套，所以原题顺序按原文教学不安全。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Procedure 5-3: Handling an Exposure Incident: Client Injury","printedPage":"141-143","pdfPage":636}]},{"id":"practice-comprehensive-006","question":{"en":"In order to help avoid costly mistakes in the future, it is important that you take all EXCEPT which of the following simple steps in your social media venues?","zh":"为了避免将来犯下代价高昂的错误，在社交媒体平台上应采取以下所有简单措施，但哪一项除外？"},"choices":[{"id":"a","en":"Use social media to communicate with peers and clients.","zh":"使用社交媒体与同行和客户沟通。"},{"id":"b","en":"Emphasize a strong work ethic as well as good hygiene.","zh":"强调良好的职业道德和卫生习惯。"},{"id":"c","en":"Manage your personal pages or walls.","zh":"管理你的个人页面或动态墙。"},{"id":"d","en":"Post helpful content.","zh":"发布有帮助的内容。"}],"sourceAnswer":{"en":"Emphasize a strong work ethic as well as good hygiene.","zh":"强调良好的职业道德和卫生习惯。"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"006"}],"reviewReason":{"en":"The EXCEPT item says emphasizing work ethic and hygiene is not a step for avoiding social-media mistakes. That answer is unrelated to the other platform-safety actions and does not teach one clear rule.","zh":"这道 EXCEPT 题把强调职业道德和卫生说成不是避免社交媒体错误的步骤。这个答案和其他平台安全做法无关，也教不出一条清楚规则。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Life Skills - Social Media","printedPage":"10-17","pdfPage":505}]},{"id":"practice-comprehensive-011","question":{"en":"___________ is the #1 cause of daytime fatigue.","zh":"_____是导致日间疲劳的首要原因。"},"choices":[{"id":"a","en":"Lack of water","zh":"缺水"},{"id":"b","en":"Lack of minerals","zh":"缺乏矿物质"},{"id":"c","en":"Lack of protein","zh":"缺乏蛋白质"},{"id":"d","en":"Lack of vitamins","zh":"缺乏维生素"}],"sourceAnswer":{"en":"Lack of water","zh":"缺水"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"011"}],"reviewReason":{"en":"The source presents lack of water as the universal number-one cause of daytime fatigue. Fatigue has many medical and lifestyle causes, and the exact ranking is unsupported.","zh":"原题把缺水说成白天疲劳的全球第一原因。疲劳有很多医学和生活方式原因，这个精确排名没有依据。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Workplace Health - Fatigue and Hydration","printedPage":"90-94","pdfPage":585}]},{"id":"practice-comprehensive-034","question":{"en":"It is important for you to report all of your income, even cash tips that are not shown on your paycheck, because.","zh":"必须申报全部收入，包括工资单上未显示的现金小费，因为_____。"},"choices":[{"id":"a","en":"you will get a bigger return on your taxes if you report income that was not included in your paycheck","zh":"申报工资单之外的收入会让退税额更高"},{"id":"b","en":"you will encourage future clients to tip more frequently and more generously","zh":"会鼓励未来客户更频繁、更慷慨地给小费"},{"id":"c","en":"you will increase the value of those tips in real dollars over the long term","zh":"从长期看会提高这些小费的实际价值"},{"id":"d","en":"you will increase the amount of Social Security benefits you\'ll receive after retirement","zh":"会增加退休后领取的社会保障福利金额"}],"sourceAnswer":{"en":"you will increase the amount of Social Security benefits you\'ll receive after retirement","zh":"会增加退休后领取的社会保障福利金额"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"034"}],"reviewReason":{"en":"The item gives U.S. tax and Social Security benefit advice without jurisdiction, employment status, or current-law context. This legally and financially sensitive claim requires current specialist review.","zh":"这道题给出美国税务和社会保障福利建议，却没有说明管辖区、就业状态或现行法律背景。这种法律和财务敏感说法需要由当前专业人员审核。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Career Planning - Income and Taxes","printedPage":"230-260","pdfPage":725}]},{"id":"practice-comprehensive-050","question":{"en":"Which is TRUE of the difference between dermatitis and eczema?","zh":"关于皮炎与湿疹的区别，以下哪一项是对的？"},"choices":[{"id":"a","en":"Eczema appears swollen, red, and hot to the touch, whereas dermatitis appears only as lesions.","zh":"湿疹表现为肿胀、发红且摸起来发热，而皮炎只表现为皮损。"},{"id":"b","en":"There are multiple types of dermatitis, but only one type of eczema.","zh":"皮炎有多种类型，但湿疹只有一种。"},{"id":"c","en":"Eczema is painful and itchy, whereas dermatitis can often appear as a rash-like irritation.","zh":"湿疹疼痛且发痒，而皮炎常表现为皮疹样刺激。"},{"id":"d","en":"Eczema is not contagious, whereas dermatitis is.","zh":"湿疹不传染，而皮炎会传染。"}],"sourceAnswer":{"en":"Eczema is painful and itchy, whereas dermatitis can often appear as a rash-like irritation.","zh":"湿疹疼痛且发痒，而皮炎常表现为皮疹样刺激。"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"050"}],"reviewReason":{"en":"The source presents eczema and dermatitis as separate conditions with a fixed symptom contrast. Eczema is a form of dermatitis, and the textbook does not support this as a reliable either-or distinction.","zh":"原题把 eczema 和 dermatitis 说成症状固定对比的两种病。eczema 是 dermatitis 的一种，教材并不支持这种可靠的二选一区分。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Skin Disorders - Dermatitis and Eczema","printedPage":"82-89","pdfPage":106}]},{"id":"practice-comprehensive-051","question":{"en":"On which part of the face is the nail technician MOST likely to experience skin allergies?","zh":"美甲师面部的哪个部位最可能出现皮肤过敏？"},"choices":[{"id":"a","en":"lips","zh":"嘴唇"},{"id":"b","en":"bridge of nose","zh":"鼻梁"},{"id":"c","en":"forehead","zh":"前额"},{"id":"d","en":"cheeks","zh":"面颊"}],"sourceAnswer":{"en":"cheeks","zh":"面颊"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"051"}],"reviewReason":{"en":"The source keys cheeks as the face area where nail technicians are most likely to experience skin allergies. The textbook discusses product allergy and exposure but does not support this unique body-location claim.","zh":"原题把脸颊说成美甲师最容易出现皮肤过敏的面部位置。教材讨论产品过敏和接触，但并不支持这个唯一部位说法。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Skin Disorders - Product Allergies and Sensitization","printedPage":"82-84","pdfPage":106}]},{"id":"practice-comprehensive-072","question":{"en":"Shaving the legs within 48 hours of receiving a pedicure can have what result?","zh":"接受足部美甲护理前48小时内剃腿毛可能产生什么结果？"},"choices":[{"id":"a","en":"decreased circulation in the legs","zh":"腿部血液循环减少"},{"id":"b","en":"significant heat sensitivity","zh":"对热显著敏感"},{"id":"c","en":"exfoliating scrub not working effectively","zh":"去角质磨砂膏无法有效发挥作用"},{"id":"d","en":"increased risk of irritation or infection","zh":"刺激或感染风险增加"}],"sourceAnswer":{"en":"increased risk of irritation or infection","zh":"刺激或感染风险增加"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"072"}],"reviewReason":{"en":"The source asks about shaving within 48 hours before a pedicure. Milady advises clients not to shave or wax their legs within 24 hours before a pedicure, so the source\'s exact time window is not supported.","zh":"原题问足部护理前 48 小时内剃毛。Milady 建议客人在足部护理前 24 小时内不要剃腿毛或热蜡，所以原题的精确时间并不被支持。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Mycobacterium","printedPage":"108","pdfPage":603}]},{"id":"practice-comprehensive-075","question":{"en":"Which of the following is true?","zh":"以下哪一项是正确的？"},"choices":[{"id":"a","en":"As you press down, the machine speed decreases; as you reduce pressure, the speed increases.","zh":"向下按压时机器速度降低；减小压力时速度提高。"},{"id":"b","en":"As you press down, the machine unlocks; as you reduce pressure, the machine locks.","zh":"向下按压时机器解锁；减小压力时机器锁定。"},{"id":"c","en":"As you press down, the machine locks; as you reduce pressure, the machine unlocks.","zh":"向下按压时机器锁定；减小压力时机器解锁。"},{"id":"d","en":"As you press down, the machine speed increases; as you reduce pressure, the speed decreases.","zh":"向下按压时机器速度提高；减小压力时速度降低。"}],"sourceAnswer":{"en":"As you press down, the machine speed increases; as you reduce pressure, the speed decreases.","zh":"向下按压时机器速度提高；减小压力时速度降低。"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"075"}],"reviewReason":{"en":"The keyed statement says pressing down always increases machine speed. That behavior applies only to a particular variable-speed foot control, not to every electric file or handpiece control.","zh":"原题说往下踩总会加快机器速度。这种表现只适用于某一种变速脚控，不是每一台电动磨甲机或手柄控制都这样。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Electric Filing - Speed Controls","printedPage":"230-240","pdfPage":254}]},{"id":"practice-comprehensive-115","question":{"en":"______ destroys ALL microbial life","zh":"_____会消灭所有微生物生命。"},"choices":[{"id":"a","en":"Sanitization","zh":"卫生处理"},{"id":"b","en":"Disinfection","zh":"消毒"},{"id":"c","en":"Sterilization","zh":"灭菌"},{"id":"d","en":"Cleaning","zh":"清洁"}],"sourceAnswer":{"en":"Sanitization","zh":"卫生处理"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"115"}],"reviewReason":{"en":"The source marks sanitization as destroying all microbial life. Established fact: sterilization destroys all microbial life, including spores.","zh":"原题把 sanitization（清洁卫生处理）标成能杀死所有微生物。既定事实是：sterilization（灭菌）才能杀死所有微生物，包括芽孢。"},"authorityRefs":[]},{"id":"practice-comprehensive-123","question":{"en":"Which of the following is one of the two types of parasites commonly encountered in the salon and spa?","zh":"以下哪一项是沙龙和水疗中心常见的两种寄生虫之一？"},"choices":[{"id":"a","en":"Mycobacteria","zh":"真菌"},{"id":"b","en":"HIV","zh":"人类免疫缺陷病毒（HIV）"},{"id":"c","en":"Pediculous capitis","zh":"疥疮"},{"id":"d","en":"Pus","zh":"脓液"}],"sourceAnswer":{"en":"Pediculous capitis","zh":"疥疮"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"123"}],"reviewReason":{"en":"The keyed term \'Pediculous capitis\' is misspelled. The recognized condition is pediculosis capitis, and the damaged key should not be silently corrected in source custody.","zh":"原题术语 Pediculous capitis 拼写错误。公认病名是 pediculosis capitis（头虱病）。在保留原文的规则下，不能悄悄改正这个损坏的答案。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Infection Control - Parasites","printedPage":"108-109","pdfPage":603}]},{"id":"practice-comprehensive-140","question":{"en":"Of all the elements known to science today, _________ occur naturally on earth","zh":"当今科学已知的所有元素中，有_____种天然存在于地球上。"},"choices":[{"id":"a","en":"89","zh":"89"},{"id":"b","en":"18","zh":"18"},{"id":"c","en":"98","zh":"98"},{"id":"d","en":"19","zh":"19 种"}],"sourceAnswer":{"en":"98","zh":"98"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"140"}],"reviewReason":{"en":"The source gives an exact count of 98 elements occurring naturally on Earth. The boundary depends on how trace and short-lived elements are classified, so this unsupported exact figure is not safe to teach.","zh":"原题给出地球上自然存在的元素正好 98 种。这个界限取决于如何划分痕量和短寿命元素，所以这个没有依据的精确数字不适合教学。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Chemistry and Chemical Safety - Elements","printedPage":"154-155","pdfPage":649}]},{"id":"practice-comprehensive-143","question":{"en":"__________ is an example of a compound molecule","zh":"_____是化合物分子的例子。"},"choices":[{"id":"a","en":"Ice melting to become water","zh":"冰融化成水"},{"id":"b","en":"Water evaporating into the air","zh":"水蒸发到空气中"},{"id":"c","en":"Exposed metal rusting","zh":"裸露金属生锈"},{"id":"d","en":"Liquid nail polish hardening","zh":"液体指甲油变硬"}],"sourceAnswer":{"en":"Exposed metal rusting","zh":"裸露金属生锈"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"143"}],"reviewReason":{"en":"The source asks for a compound molecule but keys exposed metal rusting. Rusting is a chemical reaction; it is not itself an example of a compound molecule.","zh":"题目要的是化合物分子，原题答案却是暴露金属生锈。生锈是化学反应，它本身不是化合物分子的例子。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Chemistry and Chemical Safety - Molecules and Chemical Changes","printedPage":"156-157","pdfPage":651}]},{"id":"practice-comprehensive-152","question":{"en":"Electrical current is measured by __________","zh":"电流用_____测量。"},"choices":[{"id":"a","en":"watts","zh":"瓦特"},{"id":"b","en":"amperes","zh":"安培"},{"id":"c","en":"ohms","zh":"欧姆"},{"id":"d","en":"volts","zh":"伏特"}],"sourceAnswer":{"en":"ohms","zh":"欧姆"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"152"}],"reviewReason":{"en":"The source keys ohms for electrical current. Current is measured in amperes; ohms measure resistance, so the keyed answer is incorrect.","zh":"原题用 ohms（欧姆）表示电流。电流用 amperes（安培）计量；欧姆计量的是电阻，所以原题答案不正确。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Electricity - Electrical Measurements","printedPage":"184-191","pdfPage":679}]},{"id":"practice-comprehensive-153","question":{"en":"Walts measure __________","zh":"瓦特测量的是__________"},"choices":[{"id":"a","en":"how much electrical energy is being used in one second","zh":"一秒内使用的电能量"},{"id":"b","en":"the strength of an electrical current","zh":"电流强度"},{"id":"c","en":"the pressure or force that pushes electrical current through a conductor","zh":"推动电流通过导体的压力或作用力"},{"id":"d","en":"the resistance of an electrical current","zh":"电流的电阻"}],"sourceAnswer":{"en":"how much electrical energy is being used in one second","zh":"一秒内使用的电能量"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"153"}],"reviewReason":{"en":"The stem misspells watts as \'Walts.\' Although the definition describes watts, source custody forbids silently repairing the tested term.","zh":"题目把 watts 拼成 Walts。虽然定义描述的是瓦特，但保留原文的规则禁止悄悄修好被考的术语。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Electricity - Watts","printedPage":"184-191","pdfPage":679}]},{"id":"practice-comprehensive-164","question":{"en":"Being a person who always sees the glass as half full is one important way to be which of the following?","zh":"总是把杯子看成半满，是保持以下哪种品质的一种重要方法？"},"choices":[{"id":"a","en":"Positive","zh":"积极"},{"id":"b","en":"Reliable","zh":"可靠"},{"id":"c","en":"Professional","zh":"专业"},{"id":"d","en":"Respectful","zh":"尊重他人"}],"sourceAnswer":{"en":"Positive","zh":"积极"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"164"}],"reviewReason":{"en":"The stem depends on the culture-specific idiom \'glass as half full.\' The item tests English figurative language more than professional knowledge and is unsuitable for the ESL teaching pool.","zh":"题目依赖英语习语“杯子是半满的”。它更多在考英语比喻，而不是专业知识，不适合英语学习者教学题库。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Life Skills - Positive Attitude","printedPage":"3-15","pdfPage":498}]},{"id":"practice-comprehensive-172","question":{"en":"Which job will be LEAST satisfying to a nail technician who enjoys training and educating others?","zh":"对于喜欢培训和教育他人的美甲师来说，以下哪份工作最不能带来满足感？"},"choices":[{"id":"a","en":"distributor sales consultant","zh":"经销商销售顾问"},{"id":"b","en":"manufacturer educator","zh":"制造商教育师"},{"id":"c","en":"independent educator","zh":"独立教育师"},{"id":"d","en":"beauty school instructor","zh":"美容学校教师"}],"sourceAnswer":{"en":"distributor sales consultant","zh":"经销商销售顾问"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"172"}],"reviewReason":{"en":"The source says distributor sales consultant is least satisfying for someone who enjoys training. Distributor educators and sales consultants often teach products, so the key is not uniquely defensible.","zh":"原题说喜欢培训的人最不满意经销商销售顾问工作。经销商教育人员和销售顾问常常也教产品，所以这个答案并不能唯一成立。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"Career Planning - Job Opportunities","printedPage":"219-230","pdfPage":715}]},{"id":"practice-comprehensive-175","question":{"en":"Which body system is LEAST important for the nail technician to understand?","zh":"对于美甲师而言，最不需要了解的是哪个人体系统？"},"choices":[{"id":"a","en":"endocrine","zh":"内分泌"},{"id":"b","en":"digestive","zh":"消化"},{"id":"c","en":"reproductive","zh":"生殖"},{"id":"d","en":"integumentary","zh":"皮肤"}],"sourceAnswer":{"en":"reproductive","zh":"生殖"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"175"}],"reviewReason":{"en":"The source asks which body system is least important for a nail technician. Relative importance is subjective and does not create a unique factual answer.","zh":"原题问哪个身体系统对美甲师最不重要。相对重要性是主观的，不能产生唯一的事实答案。"},"authorityRefs":[{"source":"Milady Standard Foundations","section":"General Anatomy - Body Systems","printedPage":"18-57","pdfPage":42}]},{"id":"practice-comprehensive-186","question":{"en":"What is NOT a characteristic of healthy sin?","zh":"下列哪项不是健康皮肤的特征？"},"choices":[{"id":"a","en":"fine grained","zh":"纹理细腻"},{"id":"b","en":"regid","zh":"僵硬的"},{"id":"c","en":"flexible","zh":"有柔韧性"},{"id":"d","en":"slightly moist","zh":"略微湿润"}],"sourceAnswer":{"en":"regid","zh":"僵硬的"},"sources":[{"book":"Theory Nail-Milady Comprehensive - English","itemRef":"186"}],"reviewReason":{"en":"The source repeats the healthy-skin question with misspellings in both the stem and keyed choice (\'sin\' and \'regid\'). The clean duplicate comprehensive-048 is retained, so this damaged version is held for review.","zh":"原题重复了健康皮肤那道题，题干和原题选项都有拼写错误（sin 和 regid）。已保留干净的重复题 comprehensive-048，所以这个损坏版本继续待审核。"},"authorityRefs":[{"source":"Milady Standard Nail Technology 8th Edition","section":"Skin Structure - Characteristics of Healthy Skin","printedPage":"80-81","pdfPage":104}]}]}')}}]);